def _is_unbound_accessory_availability_question(question: str) -> bool:
    """Recognize a short accessory-inclusion/availability ask without a SKU."""
    text = str(question or "").strip()
    if not text or len(text) > 80:
        return False
    # “炉头推荐/哪款炉头” is a product-selection request, not a question
    # about whether an accessory is included or sold separately. Let the
    # semantic recommendation route own that decision instead of asking for
    # an identity slot prematurely.
    if any(term in text for term in ("推荐", "哪款", "哪个", "怎么选", "适合", "帮我选", "帮我挑")):
        return False
    subjects = (
        "气罐", "配件", "附件", "炉头", "点火器", "点火装置", "调节开关", "火力调节", "调节旋钮",
        "转接头", "转换头", "适配头", "管线", "连接管", "连接软管", "气管", "软管",
    )
    markers = (
        "有没有", "有吗", "是否有", "是否配有", "是否包含", "包含吗", "一起", "组合", "选择", "可配",
        "单独买", "单独购买", "单独卖", "单卖", "分开卖", "有卖", "卖吗", "卖么", "另购", "增配",
    )
    # Customers often shorten “点火器/点火装置” to “点火” when they ask
    # whether it can be combined with a regulating switch.  Treat that as
    # an accessory noun only in an accessory/combination context; a bare
    # ignition-how-to question remains on the usage-care route.
    shorthand_ignition_accessory = (
        "点火" in text
        and any(term in text for term in ("配件", "调节开关", "火力调节", "调节旋钮", "一起", "组合", "选择", "增配"))
    )
    if not any(subject in text for subject in subjects) and not shorthand_ignition_accessory:
        return False
    separate_sale_wording = bool(re.search(r"(?:单独|分开|另外|另有).{0,8}(?:卖|买|购)", text))
    return any(marker in text for marker in markers) or separate_sale_wording or bool(
        re.search(r"(?:气罐|配件|附件|炉头|点火器|点火装置|调节开关|火力调节|调节旋钮|转接头|转换头|适配头)\s*有[?？]?$", text)
    )






def _is_unbound_environmental_fuel_safety_question(question: str) -> bool:
    text = str(question or "").strip()
    return bool(
        any(term in text for term in ("帐篷", "密闭空间", "封闭空间", "一氧化碳"))
        and any(term in text for term in ("酒精炉", "液体酒精", "固体酒精", "燃气炉", "炉具", "明火"))
    )


def _apply_environmental_fuel_safety_boundary(question: str, agent_result: dict) -> dict:
    """Keep unbound combustion-in-enclosure questions actionably safe.

    The semantic route may correctly identify a knowledge question but still
    return only a catalogue gap when the exact fuel wording is absent from the
    knowledge base. Safety must not depend on that retrieval hit. This
    boundary is deliberately limited to turns without an explicit SKU; named
    products continue through their same-SKU evidence contract.
    """
    if not isinstance(agent_result, dict):
        return agent_result
    text = str(question or "").strip()
    if not _is_unbound_environmental_fuel_safety_question(text):
        return agent_result
    if customer_agent_service._extract_skus(text):
        return agent_result
    answer = customer_agent_intent_service._compose_safety_usage_care_answer(text)
    if not answer:
        return agent_result
    agent_result.update({
        "intent": "knowledge_base_answer",
        "answer_type": "knowledge_base_answer",
        "answer": answer,
        "sku": None,
        "results": [],
        "result_skus": [],
        "candidate_skus": [],
        "sources": [{
            "type": "safety_guidance",
            "label": "燃烧型炉具封闭空间安全边界",
        }],
        "evidence": [],
        "actions": [],
        "needs_clarification": False,
        "confidence": "high",
        "uncertainty": "confirmed",
        "warnings": [],
        "suggested_followups": [],
        "followups": [],
        "steps": [{
            "type": "safety_guidance",
            "label": "执行封闭空间燃烧安全边界",
            "detail": "不因知识库缺少同词条而放宽燃烧安全结论",
            "ok": True,
        }],
        "skip_polish": True,
    })
    metadata = agent_result.get("answer_metadata") if isinstance(agent_result.get("answer_metadata"), dict) else {}
    metadata.update({
        "source": "bounded_environmental_safety_guidance",
        "evidence_status": "matched",
        "semantic_safety_boundary": True,
    })
    agent_result["answer_metadata"] = metadata
    debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
    debug.update({
        "agent_mode": "semantic_environmental_fuel_safety_boundary",
        "semantic_safety_boundary": True,
    })
    agent_result["debug"] = debug
    return agent_result


def _looks_like_unbound_canister_compatibility_question(question: str) -> bool:
    """Recognize a gas-canister connection/adapter ask without an identity.

    A phrase such as “这个用哪个气罐，需要转接头吗” contains a catalogue noun
    and a recommendation verb, but the customer is primarily asking whether the
    interface is compatible.  Keep that compatibility concern ahead of the
    gas-canister catalogue route unless a concrete product anchor is present.
    """
    text = str(question or "").strip()
    if not text or not any(term in text for term in ("气罐", "气瓶", "燃气罐", "通用罐")):
        return False
    compatibility_terms = (
        "能不能接", "能否接", "能接", "接上", "连接", "接口", "转接头", "转换头",
        "适配头", "适配", "兼容", "通用气罐", "需要转接", "配转接",
    )
    if not any(term in text for term in compatibility_terms):
        return False
    # “连接时要注意什么” asks for general operating/safety guidance; it
    # does not claim a specific canister is compatible with a specific stove.
    # Keep the identity gate for concrete yes/no or adapter decisions.
    if any(term in text for term in ("注意什么", "要注意", "注意事项", "怎么连接", "如何连接", "连接时")):
        return False
    return not (customer_agent_service._extract_skus(text) or SKU_RE.search(text))


def _looks_like_home_or_electric_stove_safety_question(question: str) -> bool:
    """Recognize a safety/compatibility scope, not a product browse request."""
    text = str(question or "").strip()
    if not text:
        return False
    environment_terms = ("家里", "家中", "室内", "电磁炉", "电池炉", "电陶炉", "电热炉")
    safety_predicates = (
        "不适合", "不建议", "不能", "不可", "不能放", "不能用", "能不能", "可以吗", "能用吗", "适合吗",
    )
    if not any(term in text for term in environment_terms):
        return False
    if not any(term in text for term in safety_predicates):
        return False
    # “推荐适合家里用的炉具” is a genuine browse request; a negative or
    # compatibility predicate is required before this safety boundary wins.
    return not any(term in text for term in ("推荐", "哪款", "哪个", "怎么选", "帮我选", "帮我挑")) or any(
        term in text for term in ("不适合", "不建议", "不能", "不可", "不能放", "不能用")
    )


def _looks_like_category_availability_question(question: str) -> bool:
    """Recognize a bare category availability ask for card-scope hygiene."""
    text = str(question or "").strip()
    if not text or SKU_RE.search(text):
        return False
    if not any(term in text for term in ("有没有", "有吗", "有无", "有卖", "卖吗", "还有吗", "没有")):
        return False
    if any(term in text for term in ("推荐", "适合", "哪款", "哪个", "怎么选", "怎么用", "里面", "包括", "包含", "套装")):
        return False
    return bool(_specific_category_availability_subject(text)) or any(
        term in text
        for term in ("杯子", "水杯", "水壶", "锅具", "炉具", "炉子", "餐具", "配件", "收纳包", "收纳袋")
    )


def _specific_category_availability_subject(question: str) -> str:
    """Extract a specific product subtype from a short availability ask."""
    text = str(question or "").strip().strip("?？!！。 ")
    if not text or SKU_RE.search(text):
        return ""
    subject = ""
    for pattern in (
        r"^(?:有没有|有无|有卖)\s*(?P<subject>[A-Za-z0-9\u4e00-\u9fff-]{2,20}?)(?:卖|销售)?$",
        r"^(?P<subject>[A-Za-z0-9\u4e00-\u9fff-]{2,20}?)(?:有吗|有卖吗|卖吗|卖么|还有吗)$",
    ):
        match = re.fullmatch(pattern, text)
        if match:
            subject = str(match.group("subject") or "").strip()
            break
    if not subject or subject.startswith(("什么", "其他", "其它", "别的", "适合")):
        return ""
    # Selection qualifiers belong to the recommendation route.  Keeping them
    # in the availability subject would turn “有没有推荐的卡式炉” into a
    # literal product subtype named “推荐的卡式炉” and emit a false no-match.
    if subject.startswith("推荐"):
        return ""
    if any(term in text for term in ("单独", "单卖", "配件卖", "点火器", "调节开关", "管线", "连接管")):
        return ""
    if subject in {
        "杯", "杯子", "水杯", "水具", "水壶", "壶", "锅", "锅具", "炉", "炉具", "炉子",
        "餐具", "配件", "附件", "收纳包", "收纳袋", "商品", "产品",
    }:
        return ""
    return subject if subject.endswith(("杯", "壶", "锅", "炉", "盘", "袋", "包", "配件", "餐具")) else ""


def _looks_like_page_current_item_availability_question(question: str) -> bool:
    """Recognize a current-page component availability ask.

    The page marker supplies identity; the availability/component vocabulary
    supplies intent.  Explicit browse language still belongs to the
    category-recommendation route, so this boundary cannot swallow a genuine
    multi-product request.
    """
    text = str(question or "").strip()
    if not text or "当前商品：" not in text:
        return False
    # Only the customer's predicate before the page marker defines the
    # availability target.  Product nouns inside the page title (for example
    # “水壶” or “锅具”) must not turn a fuel/material question into a
    # component-availability request.
    predicate = text.split("当前商品：", 1)[0].strip()
    if not any(term in predicate for term in ("有没有", "有吗", "有无", "没有")):
        return False
    if not any(term in predicate for term in ("炉头", "炉芯", "配件", "水壶", "锅", "炉具")):
        return False
    return not any(term in predicate for term in ("推荐", "哪些", "哪款", "哪个", "其他", "还有"))


def _is_plural_catalogue_recommendation_request(question: str) -> bool:
    text = str(question or "").strip()
    if not text or any(term in text for term in ("哪个", "哪款", "优先选", "该选", "还是")):
        return False
    return any(term in text for term in ("有哪些", "哪些", "哪一些", "什么产品", "什么锅", "几款", "几种"))


def _looks_like_recommendation_request(text: str) -> bool:
    value = str(text or "").strip()
    if not value:
        return False
    if customer_agent_intent_service._looks_like_fuel_storage_comparison_question(value):
        return False
    if _looks_like_home_or_electric_stove_safety_question(value):
        return False
    # “想买 X，有哪些适合 Y 的选择” is a selection request whose answer
    # should be a shortlist, not an exhaustive category dump.  Keep this
    # generic grammatical adapter here only for the deterministic outage/
    # compatibility planner; the healthy semantic preplan remains the primary
    # owner of route meaning.
    if (
        any(term in value for term in ("想买", "想找", "需要", "帮我选"))
        and any(term in value for term in ("选择", "适合"))
        and any(term in value for term in ("有哪些", "哪些", "哪几", "哪款"))
    ):
        return True
    if any(term in value for term in ("有哪些", "哪些", "哪一些", "找")) and not any(
        term in value for term in ("推荐", "哪款", "选什么", "帮我选", "帮我挑", "推荐一个", "推荐几个")
    ):
        if any(term in value for term in ("轻便", "轻量", "不要太重", "比较轻", "预算低", "预算不高", "便宜", "新手", "徒步", "卡式炉", "酒精炉", "双人", "两个人", "两人")):
            return False
    if _contains_explicit_negative_product_marker(value):
        if any(term in value for term in ("推荐", "推荐一下", "推荐一个", "推荐几个", "有什么", "有哪些")):
            return True
    explicit_recommendation_terms = ("推荐", "哪款", "选什么", "用什么", "帮我选", "帮我挑", "合适", "适合")
    selection_request_terms = (
        *explicit_recommendation_terms,
        "哪个", "想要一款", "想找一款", "需要一款", "要一款",
    )
    product_terms = ("锅", "套锅", "单锅", "烤盘", "煎盘", "炉", "炉具", "酒精炉", "壶", "水壶", "餐具", "套装", "挡风板", "防风板", "炉芯", "炉心", "内胆", "气罐", "收纳包", "收纳袋", "配件")
    cookware_terms = ("锅", "锅具", "单锅", "套锅")
    scenario_terms = ("野餐", "露营", "徒步", "爬山", "公园", "周末", "两个人", "三个人", "一个人", "轻便", "轻量")
    open_purchase_decision_terms = (
        "想买", "买个", "买口", "买套", "买一套", "买哪个", "该买", "应该买",
        "想要一款", "想找一款", "需要一款", "要一款",
    )
    if (
        not _looks_like_purchase_channel_question(value)
        and any(term in value for term in open_purchase_decision_terms)
        and any(term in value for term in product_terms)
        and (any(term in value for term in scenario_terms) or any(term in value for term in selection_request_terms))
    ):
        return True
    if (
        any(term in value for term in ("只想买", "只买", "只要", "其他不要", "不要其他"))
        and any(term in value for term in product_terms)
        and not _looks_like_purchase_channel_question(value)
    ):
        return True
    if _looks_like_purchase_channel_question(value) and not any(term in value for term in explicit_recommendation_terms):
        return False
    single_person_terms = ("一个人用", "一人用", "单人用", "1人用", "1-2人用", "1－2人用", "适合一个人", "适合一人", "适合单人")
    open_purchase_terms = ("想买", "买个", "买口", "推荐", "适合", "那种", "有没有", "帮我选", "帮我挑")
    if (
        not SKU_RE.search(value)
        and "「" not in value
        and "」" not in value
        and any(term in value for term in cookware_terms)
        and any(term in value for term in single_person_terms)
        and any(term in value for term in open_purchase_terms)
    ):
        return True
    if any(term in value for term in ("轻便", "轻量", "不要太重", "预算低", "预算不高", "预算低一点", "便宜点", "推荐一个", "推荐几个")) and any(
        term in value for term in ("水杯", "杯", "钛杯", "水壶", "锅具", "锅", "炉具", "炉子", "装备")
    ):
        return True
    if any(term in value for term in ("公园", "野餐", "徒步", "露营")) and any(term in value for term in ("带什么", "装备", "轻便")):
        return True
    return any(term in value for term in selection_request_terms) and any(term in value for term in product_terms)


def _looks_like_purchase_channel_question(text: str) -> bool:
    value = str(text or "").strip()
    if not value:
        return False
    # ``怎么买``/``买到`` also occur in ordinary product selection questions
    # (e.g. “杯子怎么买”“燃料酒精随处能买到吗”).  Those must stay on the
    # product/fuel semantic route; otherwise the FAQ fast path exposes the
    # internal listing-channel table instead of answering the customer's need.
    explicit_channel_terms = (
        "购买渠道",
        "销售渠道",
        "购买链接",
        "商品链接",
        "有链接",
        "链接吗",
        "官网",
        "官方店",
        "旗舰店",
        "淘宝",
        "京东",
        "店铺",
        "下单入口",
    )
    if any(term in value for term in explicit_channel_terms):
        return True
    if any(term in value for term in ("哪里买", "去哪买", "去哪儿买", "哪里可以买", "在哪买", "在哪里买")):
        return True
    if any(term in value for term in ("燃料", "酒精", "医用", "气罐", "炉具", "炉子", "水壶", "杯子", "锅具", "锅")):
        return False
    return False




def _is_product_usage_care_question(question: str) -> bool:
    text = str(question or "").strip()
    if not text:
        return False
    if any(term in text for term in _PURE_AFTERSALES_FLOW_TERMS):
        return False
    # A general fuel-definition/availability question is educational usage
    # guidance even when it contains purchase wording such as “哪里能买到”.
    # Keep it out of the catalogue/purchase-channel route so the answer can
    # explain the fuel-vs-medical-alcohol boundary without inventing a SKU.
    if customer_agent_intent_service._looks_like_general_fuel_definition_question(text):
        return True
    # A purchase-channel ask about a consumable (for example, where to buy
    # 95% alcohol) is not a request for stove usage guidance.  Let the FAQ /
    # purchase-channel path answer it without inheriting catalogue results.
    if _looks_like_purchase_channel_question(text) and not _looks_like_recommendation_request(text):
        return False
    if customer_agent_intent_service._looks_like_water_container_capability_question(text):
        return False
    # Compatibility asks need an explicit confirmed/unconfirmed conclusion;
    # do not let the formal heat_source field heuristic downgrade them to a
    # bare product-detail field response.
    if _looks_like_compatibility_usage_question(text):
        return True
    if customer_agent_intent_service._looks_like_power_tradeoff_question(text):
        return True
    if customer_agent_intent_service._looks_like_utensil_material_safety_question(text):
        return True
    if customer_agent_intent_service._looks_like_contents_grounding_question(text):
        # “包含/里面有什么” is a package-composition question, not usage
        # care.  Only keep it here when the same sentence also carries an
        # explicit compatibility predicate (for example, whether a canister
        # inside a set is usable); otherwise page identity must remain on the
        # composition/detail route or be clarified without catalogue fan-out.
        return _looks_like_compatibility_usage_question(text)
    # The intent service evaluates the full cleaning/care utterance.  A local
    # detail-field heuristic may see a noun such as "冷水" but must not erase
    # that already-recognized usage/care meaning when no formal non-usage
    # field contract is present.
    if (
        customer_agent_intent_service._looks_like_usage_care_question(text)
        and not _has_non_usage_care_field_contract(text)
        and not _should_preserve_recommendation_priority(text)
    ):
        return True
    if _looks_like_product_detail_field_question(text):
        return False
    if _should_preserve_recommendation_priority(text):
        return False
    matched_usage_terms = [term for term in _USAGE_CARE_TERMS if term in text]
    if not matched_usage_terms:
        return False
    # Product nouns such as “炉头/气罐/酒精” are not usage intent by
    # themselves.  Without an action or decision predicate, a page question
    # like “是一个炉头？” or “包含酒精吗？” can be mistaken for usage care,
    # bypass the unresolved-page guard, and fan out into unrelated catalogue
    # results.  Keep this language-level boundary broad enough for natural
    # wording without binding it to a SKU or category exception.
    usage_action_markers = (
        "怎么", "如何", "能不能", "能否", "可以", "是否", "支持", "适合", "安全",
        "安装", "连接", "使用", "用", "烧", "燃烧", "放", "装", "加热", "点火",
        "存放", "多久", "漏", "拧紧", "扭紧",
    )
    if not any(marker in text for marker in usage_action_markers):
        return False
    has_product_context = bool(
        customer_agent_service._extract_skus(text)
        or SKU_RE.search(text)
        or any(term in text for term in _USAGE_CARE_PRODUCT_TERMS)
    )
    has_script_context = "客服怎么回复" in text or "怎么回复客户" in text or "客户说" in text
    return has_product_context or has_script_context or len(matched_usage_terms) >= 2


def _looks_like_compatibility_usage_question(question: str) -> bool:
    """Keep compatibility questions on the usage/safety route.

    A formal ``heat_source`` field contract is useful for ordinary product
    detail questions, but phrases such as "can this gas canister connect" ask
    for an explicit compatibility conclusion.  Letting Phase 2 entity detail
    arbitration win here produces a bare field dump and hides the required
    confirmed/unconfirmed answer.  This predicate is intentionally semantic
    (subject + compatibility marker), not SKU-specific.
    """
    value = str(question or "").strip()
    if not value:
        return False
    # Keep one compatibility ontology for the usage-care and page routes.
    # This covers marketplace phrasing such as “普通那种气罐” and
    # “燃气罐可以增配” in addition to the shorter “能不能接”.
    return (
        customer_agent_intent_service._looks_like_canister_compatibility_question(value)
        or customer_agent_intent_service._looks_like_canister_storage_fit_question(value)
        or customer_agent_intent_service._looks_like_fuel_compatibility_usage_question(value)
    )


def _should_preserve_recommendation_priority(text: str) -> bool:
    value = str(text or "").strip()
    if not value or not _looks_like_recommendation_request(value):
        return False
    clear_usage_care_terms = (
        "清洗",
        "清洁",
        "保养",
        "护理",
        "怎么洗",
        "怎么清洗",
        "怎么保养",
        "怎么护理",
        "洗碗机",
        "泡水",
        "浸泡",
        "钢丝球",
        "刮擦",
        "使用限制",
        "注意事项",
        "禁忌",
    )
    # An explicit care action owns a mixed sentence even when the customer is
    # also choosing a product.  Without this, “推荐一款不粘锅怎么清洗” was
    # treated as a browse request simply because it had no SKU, while a
    # sentence such as “有不粘涂层的锅怎么选” stays on recommendation because
    # it contains no care action.
    return not any(term in value for term in clear_usage_care_terms)


def _looks_like_product_detail_field_question(text: str) -> bool:
    value = str(text or "")
    if not value:
        return False
    field_contract = customer_field_contract.detect_field_contract(value)
    if field_contract:
        return customer_field_contract.is_supported_detail_field(field_contract.field_type)
    product_terms = ("套锅", "单锅", "酒精炉", "小方锅", "炊墨", "行山", "旋焰", "烽宴", "CW-", "CS-", "TW-")
    field_terms = (
        "有没有不粘涂层", "有涂层吗", "有没有涂层", "是不是304", "是不是不锈钢", "是不是木头",
        "手柄", "把手", "锅体", "锅盖", "盖子", "煎盘", "材质", "尺寸", "容量", "重量", "净重",
        "热源", "燃料", "支持酒精炉", "用酒精炉", "适用人群", "适合哪些人群", "适合几人", "适合几个人",
        "几个人", "几人", "人数", "洗碗机", "说明书", "官方说明书", "保修", "质保", "安装视频", "视频教程",
        "库存", "现货", "销量", "评价", "价格", "认证", "BPA", "使用限制", "冷水", "热水", "补水", "烧水"
    )
    if not any(term in value for term in product_terms) or not any(term in value for term in field_terms):
        return False
    if "洗碗机" in value and any(term in value for term in ("能放", "放进", "可以放", "适合", "能不能放")):
        return True
    usage_action_terms = ("清洗", "清洁", "保养", "护理", "怎么洗", "怎么清洗", "糊锅", "糊了", "烧糊", "刮擦", "钢丝球", "泡水", "浸泡")
    return not any(term in value for term in usage_action_terms)












def _sku_identity_key(value: str | None) -> str:
    """Normalize a displayed SKU to its stable base identity for alignment."""
    text = str(value or "").strip().upper()
    return re.sub(r"[（(][^）)]*[）)]$", "", text).strip()


def _align_answer_named_result_cards(result: dict) -> dict:
    """Keep verified rows named in the answer represented by visible cards.

    This only restores identities already present in the result packet (or its
    raw result packet).  It never turns a textual SKU into a new product hit.
    """
    if not isinstance(result, dict):
        return result
    # Clarification candidates are resolver/diagnostic options, not selected
    # catalogue results.  Do not rehydrate their raw rows into public cards.
    if (
        str(result.get("answer_type") or "").strip() == "clarification"
        or result.get("needs_clarification") is True
    ):
        return result
    answer_skus = [
        str(item or "").strip().upper()
        for item in customer_agent_service._extract_skus(str(result.get("answer") or ""))
        if str(item or "").strip()
    ]
    rows = [row for row in (result.get("results") or []) if isinstance(row, dict)]
    if rows:
        answer_text = str(result.get("answer") or "")
        name_positions: list[tuple[int, str]] = []
        for row in rows:
            sku = str(row.get("sku") or "").strip().upper()
            names = [
                str(row.get(key) or "").strip()
                for key in ("product_name_cn", "product_name_en")
                if str(row.get(key) or "").strip()
            ]
            positions = [answer_text.find(name) for name in names if answer_text.find(name) >= 0]
            if sku and positions:
                name_positions.append((min(positions), sku))
        if len(name_positions) == len(rows) and len({position for position, _ in name_positions}) == len(rows):
            answer_skus = [sku for _, sku in sorted(name_positions)]
    if not answer_skus:
        return result
    debug = result.get("debug") if isinstance(result.get("debug"), dict) else {}
    raw_rows = [row for row in (debug.get("raw_results") or []) if isinstance(row, dict)]
    row_by_identity: dict[str, tuple[str, dict]] = {}
    for row in (*rows, *raw_rows):
        sku = str(row.get("sku") or "").strip().upper()
        identity = _sku_identity_key(sku)
        if not sku or not identity:
            continue
        # A base identity is usable only when it maps to one verified row;
        # otherwise a shortened display token would be ambiguous.
        previous = row_by_identity.get(identity)
        if previous and previous[0] != sku:
            row_by_identity.pop(identity, None)
        elif identity not in row_by_identity:
            row_by_identity[identity] = (sku, row)
    if not row_by_identity:
        return result
    current_skus = [
        str(item or "").strip().upper()
        for item in (result.get("result_skus") or [])
        if str(item or "").strip()
    ]
    current_identity = {_sku_identity_key(sku) for sku in current_skus}
    existing_result_identity = {
        _sku_identity_key(str(row.get("sku") or "").strip().upper())
        for row in rows
        if str(row.get("sku") or "").strip()
    }
    restored_rows: list[dict] = []
    for answer_sku in answer_skus:
        identity = _sku_identity_key(answer_sku)
        matched = row_by_identity.get(identity)
        if matched and identity not in existing_result_identity:
            restored_rows.append(matched[1])
            existing_result_identity.add(identity)
    if restored_rows:
        result["results"] = [*rows, *restored_rows]
        rows = list(result["results"])
    # When every visible result identity is explicitly named, the prose order
    # is the customer-facing order. Keep result_skus and cards in that order so
    # “first/second”, replacement context and API evidence cannot disagree.
    named_current_skus: list[str] = []
    for answer_sku in answer_skus:
        matched = row_by_identity.get(_sku_identity_key(answer_sku))
        if matched and matched[0] in current_skus and matched[0] not in named_current_skus:
            named_current_skus.append(matched[0])
    if current_skus and set(named_current_skus) == set(current_skus):
        row_by_sku = {
            str(row.get("sku") or "").strip().upper(): row
            for row in rows
            if str(row.get("sku") or "").strip()
        }
        result["result_skus"] = named_current_skus
        result["results"] = [row_by_sku[sku] for sku in named_current_skus if sku in row_by_sku]
        result["candidate_skus"] = list(named_current_skus)
        current_skus = list(named_current_skus)
        rows = list(result["results"])
    additions: list[str] = []
    for answer_sku in answer_skus:
        identity = _sku_identity_key(answer_sku)
        matched = row_by_identity.get(identity)
        if not matched or identity in current_identity:
            continue
        additions.append(matched[0])
        current_identity.add(identity)
    if not additions:
        return result
    ordered_skus = [*current_skus, *additions]
    result["result_skus"] = ordered_skus
    existing_result_skus = {
        str(row.get("sku") or "").strip().upper()
        for row in rows
        if str(row.get("sku") or "").strip()
    }
    result["results"] = [*rows]
    for sku in additions:
        if sku in existing_result_skus:
            continue
        matched = row_by_identity.get(_sku_identity_key(sku))
        if matched:
            result["results"].append(matched[1])
            existing_result_skus.add(sku)
    result["candidate_skus"] = [
        str(item or "").strip().upper()
        for item in (result.get("candidate_skus") or [])
        if str(item or "").strip()
    ]
    for sku in additions:
        if sku not in result["candidate_skus"]:
            result["candidate_skus"].append(sku)
    return result


def _align_recommendation_result_cards(result: dict) -> dict:
    """Keep visible recommendation cards aligned with a grounded narrative.

    A validated narrative can mention several ranked candidates while an
    older post-filter leaves only the first row in ``results``.  If the other
    named candidates are present in the database-backed raw result packet and
    in the selected evidence, restore those cards; never expand from names
    that lack a matching verified row.
    """
    if not isinstance(result, dict) or str(result.get("answer_type") or "").strip() != "recommendation":
        return result
    answer = str(result.get("answer") or "")
    if not answer:
        return result
    rows: list[dict] = [row for row in (result.get("results") or []) if isinstance(row, dict)]
    debug = result.get("debug") if isinstance(result.get("debug"), dict) else {}
    raw_rows = [row for row in (debug.get("raw_results") or []) if isinstance(row, dict)]
    row_by_sku: dict[str, dict] = {}
    for row in (*rows, *raw_rows):
        sku = str(row.get("sku") or "").strip().upper()
        if sku and sku not in row_by_sku:
            row_by_sku[sku] = row
    if len(row_by_sku) < 2:
        return result
    evidence_skus = {
        str(item.get("sku") or "").strip().upper()
        for item in (result.get("evidence") or [])
        if isinstance(item, dict) and str(item.get("sku") or "").strip()
    }
    if not evidence_skus:
        return result
    answer_upper = answer.upper()
    named_rows = [
        row for sku, row in row_by_sku.items()
        if sku in evidence_skus
        and (
            sku in answer_upper
            or any(
                name and name.upper() in answer_upper
                for name in (
                    str(row.get("product_name_cn") or "").strip(),
                    str(row.get("product_name_en") or "").strip(),
                )
            )
        )
    ]
    if len(named_rows) < 2:
        return result
    ordered_rows: list[dict] = []
    seen: set[str] = set()
    for row in (*rows, *named_rows):
        sku = str(row.get("sku") or "").strip().upper()
        if sku in {str(item.get("sku") or "").strip().upper() for item in named_rows} and sku not in seen:
            ordered_rows.append(row_by_sku[sku])
            seen.add(sku)
    if len(ordered_rows) < 2:
        return result
    result["results"] = ordered_rows
    result["result_skus"] = [str(row.get("sku") or "").strip().upper() for row in ordered_rows]
    result["candidate_skus"] = list(result["result_skus"])
    return result


def _shape_answer_for_output(result: dict) -> dict:
    metadata_evidence = _field_metadata_display_evidence(result)
    metadata = result.get("answer_metadata") if isinstance(result.get("answer_metadata"), dict) else {}
    is_validated_semantic_recommendation = bool(
        str(result.get("answer_type") or "").strip() == "recommendation"
        and str(metadata.get("source") or "").strip()
        == "validated_semantic_preplan_then_same_sku_verification"
    )
    is_formal_comparison = bool(
        str(result.get("answer_type") or "").strip() == "comparison"
        and str(metadata.get("source") or "").strip() in {
            "planner_compare_formal_field_contract",
            "semantic_pairwise_compound_evidence_contract",
        }
    )
    is_sealed_field_detail = bool(
        str(result.get("answer_type") or "").strip() == "product_detail"
        and str(metadata.get("answer_policy") or "").strip() in {"field_only", "field_only_missing"}
    )
    is_safe_missing_field_detail = bool(
        str(result.get("answer_type") or "").strip() == "product_detail"
        and str(metadata.get("contract_field_type") or "").strip()
        and str(metadata.get("evidence_status") or "").strip() in {"missing", "insufficient"}
        and not str(metadata.get("evidence_value") or "").strip()
        and not bool(metadata.get("conflict_provenance"))
    )
    is_mixed_same_sku_rag_detail = bool(
        is_sealed_field_detail
        and metadata.get("semantic_same_sku_rag_owned") is True
    )
    is_conflict_provenance_detail = bool(
        str(result.get("answer_type") or "").strip() == "product_detail"
        and bool(metadata.get("conflict_provenance"))
    )
    is_sealed_same_sku_rag = bool(
        str(result.get("answer_type") or "").strip() == "product_detail"
        and str(metadata.get("contract_field_type") or "").strip() == "product_qa"
        and str(metadata.get("evidence_source") or "").strip() == "same_sku_knowledge"
        and str(metadata.get("evidence_sku") or "").strip()
    )
    is_product_qa_detail = bool(
        str(result.get("answer_type") or "").strip() == "product_detail"
        and (
            str(metadata.get("contract_field_type") or "").strip() == "product_qa"
            or str(metadata.get("evidence_source") or "").strip().startswith("product_qa:")
        )
    )
    # A sealed field answer must show the evidence that supports that exact
    # field, not an arbitrary capacity/material/color summary from the product
    # result row.  Product-row evidence remains appropriate for search,
    # comparison, and recommendation answers where multiple facts are asked.
    derived_result_evidence = (
        []
        if (
            is_sealed_field_detail
            or is_safe_missing_field_detail
            or is_product_qa_detail
            or is_formal_comparison
        )
        else _evidence_from_results(result.get("results") or [])
    )
    if is_conflict_provenance_detail:
        # A conflict answer intentionally has no confirmed field value, but
        # its same-SKU provenance receipt is still public evidence. Preserve
        # that receipt so the API cannot expose a product-bound answer with an
        # empty evidence ledger. It does not authorize either conflicting
        # value and does not change the customer-facing answer.
        explicit_evidence = [
            item for item in (result.get("evidence") or [])
            if isinstance(item, dict)
            and _display_source_type(item) == "product_conflict"
            and str(item.get("sku") or "").strip().upper()
            in {
                str(sku or "").strip().upper()
                for sku in (result.get("result_skus") or [])
                if str(sku or "").strip()
            }
        ]
    elif is_sealed_field_detail or is_safe_missing_field_detail:
        if is_mixed_same_sku_rag_detail:
            explicit_evidence = [
                item
                for item in (result.get("evidence") or [])
                if isinstance(item, dict)
                and _display_source_type(item) in {"product_qa", "knowledge_chunks"}
                and str(item.get("sku") or "").strip().upper()
                in {
                    str(sku or "").strip().upper()
                    for sku in (result.get("result_skus") or [])
                    if str(sku or "").strip()
                }
            ]
        else:
            explicit_evidence = []
    elif is_product_qa_detail:
        evidence_sku = str(metadata.get("evidence_sku") or "").strip().upper()
        if not evidence_sku:
            evidence_sku = next(
                (str(sku).strip().upper() for sku in (result.get("result_skus") or []) if str(sku or "").strip()),
                "",
            )
        explicit_evidence = [
            item for item in (result.get("evidence") or [])
            if isinstance(item, dict)
            and (not evidence_sku or str(item.get("sku") or item.get("product_id") or "").strip().upper() == evidence_sku)
            and _display_source_type(item) in {"product_qa", "knowledge_chunks", "product_conflict"}
        ]
    else:
        explicit_evidence = result.get("evidence") or []
    result["evidence"] = _normalize_display_evidence([
        *explicit_evidence,
        *metadata_evidence,
        *derived_result_evidence,
    ])
    answer_type = str(result.get("answer_type") or "").strip()
    if answer_type == "recommendation":
        # Recommendation prose is owned by the evidence-bounded semantic
        # writer. Do not re-rank or synthesize reasons with lexical templates.
        pass
    elif answer_type == "product_detail":
        question = (
            str(((result.get("answer_metadata") or {}).get("question")) or "")
            or str((((result.get("debug") or {}).get("plan") or {}).get("raw_question")) or "")
        )
        result["answer"] = _shape_product_detail_output(
            result.get("answer"),
            result.get("results") or [],
            question=question,
            answer_metadata=(result.get("answer_metadata") or {}),
        )
    elif answer_type == "product_query":
        result["answer"] = _shape_product_query_output(
            result.get("answer"),
            result.get("results") or [],
            result.get("result_skus") or [],
            question=(
                (((result.get("debug") or {}).get("intent") or {}).get("recommendation_query"))
                or (((result.get("debug") or {}).get("intent") or {}).get("semantic_query"))
                or (((result.get("debug") or {}).get("intent") or {}).get("term"))
                or str(((result.get("answer_metadata") or {}).get("question")) or "")
            ),
        )
    elif answer_type == "chat":
        result["answer"] = re.sub(
            r"\*\*(.*?)\*\*",
            r"\1",
            str(result.get("answer") or ""),
        ).strip()
    elif answer_type == "clarification" or str(result.get("intent") or "").strip() == "clarify":
        metadata = result.get("answer_metadata") if isinstance(result.get("answer_metadata"), dict) else {}
        if metadata.get("source") not in {
            "semantic_field_ambiguity_clarification",
            "semantic_pairwise_overview_uncovered_dimension_clarification",
        }:
            result["answer"] = shape_answer_tone(
                str(result.get("answer") or ""),
                intent=result.get("intent"),
                answer_type=answer_type,
            )
    # Catalogue-card cleanup is owned by the central save boundary immediately
    # after this shaping step.  Keeping it out of this formatter prevents the
    # same legacy post-processor from getting a second opportunity to rewrite
    # an already rendered semantic answer.
    if not is_validated_semantic_recommendation:
        result = _align_answer_named_result_cards(result)
    result["answer"] = _sanitize_final_answer_text(
        str(result.get("answer") or ""),
        _pick_primary_answer_source(result),
    )
    if (
        isinstance(result.get("answer_metadata"), dict)
        and result["answer_metadata"].get("source") == "semantic_field_ambiguity_clarification"
    ):
        result["answer"] = str(result.get("answer") or "").replace("多个信息", "多个字段")
    if not is_validated_semantic_recommendation:
        result = _align_recommendation_result_cards(result)
    return result


def _field_metadata_display_evidence(result: dict[str, Any]) -> list[dict[str, Any]]:
    """Expose the validated field evidence that actually supports a detail answer.

    A product-field response may use a same-SKU QA fallback after a structured
    provider safely rejects a conflicting or absent database value.  The
    selected evidence is already recorded in answer_metadata; omitting it from
    the public evidence list makes a correct answer look unsupported and lets
    unrelated product-row values appear as its source.  This adapter only
    projects metadata after checking that its SKU belongs to the sealed result.
    """
    metadata = result.get("answer_metadata")
    if not isinstance(metadata, dict):
        return []
    evidence_value = str(metadata.get("evidence_value") or "").strip()
    evidence_sku = str(metadata.get("evidence_sku") or "").strip().upper()
    canonical_field = str(metadata.get("evidence_field") or "").strip()
    source = str(metadata.get("evidence_source") or "").strip()
    if not (evidence_value and evidence_sku and canonical_field and source):
        return []

    sealed_skus = {
        str(item).strip().upper()
        for item in (result.get("result_skus") or [])
        if str(item or "").strip()
    }
    for row in result.get("results") or []:
        if isinstance(row, dict) and str(row.get("sku") or "").strip():
            sealed_skus.add(str(row.get("sku") or "").strip().upper())
    if evidence_sku not in sealed_skus:
        return []

    source_lower = source.lower()
    if source_lower.startswith("product_qa:"):
        source_type = "product_qa"
    elif "knowledge" in source_lower:
        source_type = "knowledge_chunks"
    else:
        source_type = "product_db"
    product_name = ""
    for row in result.get("results") or []:
        if not isinstance(row, dict):
            continue
        if str(row.get("sku") or "").strip().upper() == evidence_sku:
            product_name = str(row.get("product_name_cn") or row.get("product_name_en") or "").strip()
            break
    return [{
        "sku": evidence_sku,
        "product_name": product_name,
        "field_label": customer_field_contract.product_detail_field_label(canonical_field) or canonical_field,
        "value": evidence_value,
        "source_type": source_type,
        "source_layer": _layer_for_field_label(
            customer_field_contract.product_detail_field_label(canonical_field) or canonical_field
        ),
        "matched_by": "已验证字段证据",
    }]


def _normalize_display_evidence(evidence: list[dict]) -> list[dict]:
    deduped: list[dict] = []
    seen: set[tuple[str, str, str, str]] = set()
    for item in evidence or []:
        normalized = _normalize_display_evidence_item(item)
        if not normalized:
            continue
        source_type = str(normalized.get("source_type") or "").strip()
        evidence_identity = str(normalized.get("evidence_text") or "").strip()
        field_identity = str(normalized.get("question_type") or normalized.get("field_label") or "").strip()
        # Product QA rows can be emitted once by the QA shortcut and again by
        # the metadata adapter with different display labels.  Their source
        # text, not the incidental label, is the evidence identity.
        if source_type == "product_qa":
            evidence_identity = str(normalized.get("value") or evidence_identity).strip()
            field_identity = ""
        key = (
            str(normalized.get("sku") or "").strip().upper(),
            source_type,
            field_identity,
            evidence_identity,
        )
        if key in seen:
            continue
        seen.add(key)
        deduped.append(normalized)
    return deduped


def _normalize_display_evidence_item(item: dict[str, Any]) -> dict[str, Any] | None:
    if not isinstance(item, dict):
        return None
    source_type = _display_source_type(item)
    sku = str(item.get("sku") or item.get("product_id") or "").strip().upper()
    field_label = str(item.get("field_label") or "").strip()
    question_type = str(item.get("question_type") or "").strip()
    value = str(item.get("value") or "").strip()
    content = str(item.get("content") or item.get("text") or item.get("quote") or "").strip()
    if source_type == "product_qa" and field_label in {"", "product_qa", "产品 QA", "产品问答"}:
        field_label = customer_field_contract.product_detail_field_label("product_qa") or "产品问答"
    evidence_text = ""
    if field_label and value:
        evidence_text = f"{field_label} {value}".strip()
    elif content:
        evidence_text = re.sub(r"\s+", " ", content).strip("：:；;，,。 ")
    elif source_type == "product_db" and sku:
        evidence_text = ""
    elif source_type == "product_db" and not sku and not content and not field_label and not value:
        return None
    if not evidence_text and source_type != "product_db":
        return None
    if evidence_text.lower() in {"资料", "none", "null"}:
        return None
    normalized = dict(item)
    normalized["source_type"] = source_type
    normalized["source_label"] = _display_source_label(source_type)
    normalized["sku"] = sku
    if question_type:
        normalized["question_type"] = question_type
    normalized["evidence_text"] = evidence_text
    return normalized


def _display_source_type(item: dict[str, Any]) -> str:
    raw_type = str(item.get("source_type") or item.get("type") or item.get("source") or "").strip().lower()
    raw_kind = str(item.get("source_kind") or "").strip().lower()
    if raw_type == "product_db" or raw_type == "product" and not raw_kind and str(item.get("field_label") or "").strip():
        return "product_db"
    if raw_type == "product" and raw_kind == "qa":
        return "product_qa"
    if raw_type in {"knowledge_base", "knowledge", "knowledge_chunk"} or raw_kind == "kb":
        return "knowledge_chunks"
    if raw_type in {"safety_guardrail", "guardrail"}:
        return "safety_guardrail"
    if raw_type == "product" and raw_kind == "kb":
        return "knowledge_chunks"
    if raw_type == "product":
        return "product_qa" if str(item.get("content") or "").strip() else "product_db"
    return raw_type or "product_db"


def _display_source_label(source_type: str) -> str:
    return {
        "product_db": "产品基础资料",
        "product_qa": "产品问答",
        "knowledge_chunks": "知识库资料",
        "product_conflict": "结构化商品冲突",
        "safety_guardrail": "安全规则",
    }.get(source_type, source_type)




def _shape_product_query_output(
    answer: str | None,
    results: list[dict],
    result_skus: list[str] | None = None,
    question: str = "",
) -> str:
    """Compatibility shim; product-query prose stays owned by its executor.

    Product rows are evidence and UI data, not permission for a formatter to
    promote the first row into a recommendation or invent suitability prose.
    """
    del results, result_skus, question
    return str(answer or "").strip()


def _render_customer_product_qa_answer(answer: str) -> str:
    """Repair generic imported-QA grammar without changing selected evidence."""
    text = str(answer or "").strip()
    if not text:
        return ""
    text = re.sub(
        r"(?P<topic>.{2,24}?)的原因：主要由于(?P<cause>[^；。！？!?]+?)导致的\s*(?P<effect>[^，,；。！？!?]+)[，,]\s*",
        lambda match: (
            f"{match.group('topic')}通常是由于{match.group('cause')}"
            f"导致{match.group('effect')}；"
        ),
        text,
    )
    return text.replace("擦清洗", "擦拭清洁")


def _shape_product_detail_output(
    answer: str | None,
    results: list[dict],
    question: str = "",
    answer_metadata: dict[str, Any] | None = None,
) -> str:
    answer_text = str(answer or "").strip()
    evidence_field = str((answer_metadata or {}).get("evidence_field") or "").strip()
    evidence_source = str((answer_metadata or {}).get("evidence_source") or "").strip()
    if evidence_source == "specs.usage_instruction" and evidence_field in {"cleaning", "care", "usage_instruction"}:
        answer_text = _render_customer_product_qa_answer(answer_text)
    if (
        str((answer_metadata or {}).get("contract_field_type") or "").strip() == "product_qa"
        and str((answer_metadata or {}).get("evidence_status") or "").strip() == "missing"
    ):
        return _normalize_handle_material_phrase(answer_text)
    # A failed final grounding pass can still retain a semantically selected
    # same-SKU packet for the bounded recovery writer.  Its evidence status is
    # intentionally ``partial`` because one compound part may be unresolved,
    # but the answer itself may contain several independently supported parts.
    # The historical first-sentence formatter must not truncate that RAG
    # answer and erase a later conflict or capability statement.
    if (
        str((answer_metadata or {}).get("contract_field_type") or "").strip() == "product_qa"
        and str((answer_metadata or {}).get("evidence_source") or "").strip() == "same_sku_knowledge"
        and str((answer_metadata or {}).get("evidence_status") or "").strip() == "partial"
        and (
            (answer_metadata or {}).get("semantic_selected_evidence_available") is True
            or (answer_metadata or {}).get("semantic_selected_evidence_recovery") is True
        )
    ):
        return _normalize_handle_material_phrase(_render_customer_product_qa_answer(answer_text))
    # A product-QA contract can be fulfilled by either a QA row or a sealed
    # same-SKU knowledge chunk.  Both bodies have already passed evidence
    # grounding, so the generic single-sentence formatter must not discard
    # the verified details merely because the source is knowledge RAG.
    if (
        str((answer_metadata or {}).get("contract_field_type") or "").strip() == "product_qa"
        and str((answer_metadata or {}).get("evidence_status") or "").strip() == "matched"
    ):
        return _normalize_handle_material_phrase(_render_customer_product_qa_answer(answer_text))
    # A sealed same-SKU QA answer is already evidence-complete. Do not reduce
    # it to the first sentence, which would discard verified conditions and
    # reasons such as material or compatibility qualifications.
    if str((answer_metadata or {}).get("evidence_field") or "").strip() == "product_qa":
        return _normalize_handle_material_phrase(_render_customer_product_qa_answer(answer_text))
    if str((answer_metadata or {}).get("answer_policy") or "") in {
        "field_only",
        "compound_field_evidence",
        "sealed_same_sku_multi_field_evidence",
    }:
        return _normalize_handle_material_phrase(answer_text)
    if answer_text and any(
        term in answer_text
        for term in ("适用热源", "不能仅凭现有资料确认", "未显示支持", "支持酒精炉")
    ):
        return _normalize_handle_material_phrase(answer_text)
    if answer_text and (
        ("\n" in answer_text and "：" in answer_text)
        or any(
            term in answer_text
            for term in (
                "当前资料未直接标明",
                "产品问答显示",
                "知识库资料显示",
                "支持酒精炉",
                "未显示支持酒精炉",
                "不是炉具或炊具",
                "不建议按酒精炉适配产品理解",
                "当前资料未标注适用酒精炉",
                "当前资料未标注",
                "当前资料未维护",
                "无法仅凭现有资料确认",
            )
        )
        or (
            any(term in answer_text for term in ("装冷水", "装热水", "装饮用水", "装水", "开水", "沸水"))
            and any(marker in answer_text for marker in ("可以", "可装", "支持", "不建议", "不能", "避免"))
        )
    ):
        return _normalize_handle_material_phrase(answer_text)
    if results and isinstance(results[0], dict):
        row = results[0]
        sku = str(row.get("sku") or "").strip()
        name = str(row.get("product_name_cn") or row.get("product_name_en") or "").strip()
        field_values = row.get("field_values") or {}
        if isinstance(field_values, dict) and field_values:
            detail_parts = []
            for key, value in field_values.items():
                key_text = str(key)
                value_text = str(value)
                if key_text in {"材质", "主体材质"} and "、" in value_text and any(term in value_text for term in ("木", "白蜡木")):
                    primary_material, handle_material = [part.strip() for part in value_text.split("、", 1)]
                    if primary_material:
                        detail_parts.append(f"主体材质：{primary_material}")
                    if handle_material:
                        detail_parts.append(f"手柄材质：{handle_material}（手柄{handle_material}）")
                    continue
                if key_text == "手柄材质" and value_text and "手柄" not in value_text:
                    detail_parts.append(f"手柄材质：{value_text}（手柄{value_text}）")
                    continue
                detail_parts.append(f"{key}：{value}")
            detail = "；".join(detail_parts)
            prefix = f"{name}（{sku}）" if name else sku
            return _normalize_handle_material_phrase(f"{prefix}：{detail}。")
    text = answer_text
    sentence = re.split(r"[。！？!?]", text)[0].strip()
    return _normalize_handle_material_phrase(sentence + ("。" if sentence and not sentence.endswith("。") else ""))


def _normalize_handle_material_phrase(text: str) -> str:
    value = re.sub(r"\t+", "", str(text or ""))
    if not value:
        return value
    # The label already scopes the value to the handle. Older formatters could
    # append an identical parenthetical (for example
    # ``手柄材质：白蜡木（手柄白蜡木）``); collapse that duplication without
    # changing the database-backed material value.
    return re.sub(r"(手柄材质：\s*([^；。\n（）]+))（手柄\2）", r"\1", value)


def _public_intent_name(intent: str | None, answer_type: str | None = None) -> str | None:
    value = str(intent or "").strip()
    if not value:
        return value or None
    if value == "product_detail" and answer_type == "product_detail":
        return "product_detail"
    if value in {"aftersales", "company_info", "greeting"} and answer_type == "faq":
        return "customer_faq"
    if value == "recommend_products":
        return "recommendation"
    return value






def _is_generic_contents_subject(subject: str) -> bool:
    value = customer_agent_service.normalize_search_text(subject).strip()
    if not value:
        return True
    generic_terms = {
        "户外",
        "露营",
        "野营",
        "配件",
        "水壶",
        "水具",
        "锅具",
        "套锅",
        "单锅",
        "炉具",
        "炉子",
        "茶具",
        "咖啡器具",
        "杯具",
        "杯子",
        "水杯",
        "壶",
        "锅",
        "炉",
        "杯",
        "包",
    }
    if value in generic_terms:
        return True
    stripped = value
    for prefix in ("户外", "露营", "野营", "徒步", "公园", "野餐", "车载", "营地", "新手"):
        if stripped.startswith(prefix):
            stripped = stripped[len(prefix):].strip()
    return stripped in generic_terms


def _is_generic_named_product_question(question: str) -> bool:
    text = str(question or "")
    specific_terms = (
        "材质", "材料", "功率", "认证", "食品级", "水洗", "冷水", "冲洗", "清洗", "热源", "燃料",
        "表面处理", "表面工艺", "爆炒", "大火", "颜色", "容量", "重量", "尺寸", "安全", "不粘", "不沾",
    )
    if any(term in text for term in specific_terms):
        return False
    return any(
        term in text
        for term in (
            "怎么样", "介绍一下", "适合露营吗", "适合户外吗", "适合吗", "好用吗",
            "再看", "改看", "看看", "看一下",
        )
    )


def _drop_covered_canonical_name_candidates(question: str, products: list[Product]) -> list[Product]:
    """Keep distinct named products but discard a name wholly inside a longer one.

    This is identity normalization, not intent routing: when ``A`` is a
    strict canonical-name substring of ``A套装`` in the same text span, the
    latter is the only explicitly named product.  Separate mentions retain
    both products and continue through normal comparison arbitration.
    """
    normalized_question = customer_agent_service.normalize_search_text(question)
    if not normalized_question or len(products) < 2:
        return products
    spans: dict[str, tuple[int, int]] = {}
    for product in products:
        name = customer_agent_service.normalize_search_text(product.product_name_cn or "")
        if name and name in normalized_question:
            start = normalized_question.index(name)
            spans[str(product.sku or "").upper()] = (start, start + len(name))
    kept: list[Product] = []
    for product in products:
        sku = str(product.sku or "").upper()
        span = spans.get(sku)
        if not span:
            kept.append(product)
            continue
        covered = any(
            other_sku != sku
            and other_span[0] <= span[0]
            and other_span[1] >= span[1]
            and (other_span[1] - other_span[0]) > (span[1] - span[0])
            for other_sku, other_span in spans.items()
        )
        if not covered:
            kept.append(product)
    return kept


def _products_named_in_question(db: Session, question: str) -> list[Product]:
    resolved_skus: list[str] = []
    seen_resolved_skus: set[str] = set()
    for raw_sku in customer_agent_service._extract_skus(question):
        resolved_sku = _resolve_sku(db, question, raw_sku)
        normalized_sku = str(resolved_sku or "").strip().upper()
        if normalized_sku and normalized_sku not in seen_resolved_skus:
            resolved_skus.append(normalized_sku)
            seen_resolved_skus.add(normalized_sku)
    if resolved_skus:
        sku_map = {
            str(product.sku or "").strip().upper(): product
            for product in db.query(Product).filter(Product.sku.in_(resolved_skus)).all()
        }
        exact_products = [sku_map[sku] for sku in resolved_skus if sku in sku_map]
        if exact_products:
            if customer_agent_intent_service._looks_like_multi_product_relation_question(question):
                return customer_agent_intent_service._relation_products_from_question(db, question, exact_products)
            return exact_products
    subject = (
        _product_like_scope_subject(question)
        or customer_agent_intent_service._detail_subject_from_question(question)
        or question
    )
    subject = customer_field_contract.strip_leading_entity_reference_modifier(subject) or question
    if customer_agent_intent_service._looks_like_contents_grounding_question(question):
        normalized_subject = customer_agent_service.normalize_search_text(subject)
        if (
            normalized_subject
            and not customer_agent_service._extract_skus(normalized_subject)
            and len(normalized_subject) < 3
        ):
            return []
    products = db.query(Product).all()
    matched_products = customer_agent_service.resolve_named_product_candidates(question, products, subject=subject)
    matched_products = _drop_covered_canonical_name_candidates(question, matched_products)
    if customer_agent_intent_service._looks_like_multi_product_relation_question(question):
        return customer_agent_intent_service._relation_products_from_question(db, question, matched_products)
    return matched_products






def _display_value(value) -> str:
    if value in (None, ""):
        return ""
    if isinstance(value, list):
        return "，".join(_display_value(item) for item in value if item not in (None, ""))
    if isinstance(value, dict):
        label = _display_value(value.get("label"))
        item_value = _display_value(value.get("value"))
        if label and item_value:
            return item_value if label == item_value else f"{label} {item_value}"
        for key in ("value", "label", "text", "name"):
            if value.get(key) not in (None, ""):
                return _display_value(value.get(key))
        return "，".join(f"{key}: {_display_value(item)}" for key, item in value.items() if item not in (None, ""))
    return str(value).strip()


def _project_evidence_sources(agent_result: dict) -> list[dict]:
    """Expose sealed customer evidence through the standard source contract."""
    sources = [dict(item) for item in (agent_result.get("sources") or []) if isinstance(item, dict)]
    result_skus = {
        str(item.get("sku") or "").strip().upper()
        for item in (agent_result.get("results") or [])
        if isinstance(item, dict) and str(item.get("sku") or "").strip()
    }
    existing = {
        (
            str(item.get("type") or "").strip(),
            str(item.get("sku") or "").strip().upper(),
            str(item.get("field") or "").strip(),
        )
        for item in sources
    }
    for evidence in agent_result.get("evidence") or []:
        if not isinstance(evidence, dict):
            continue
        sku = str(evidence.get("sku") or "").strip().upper()
        if not sku or result_skus and sku not in result_skus:
            continue
        source_type = _display_source_type(evidence)
        field = str(evidence.get("field_label") or evidence.get("field") or "").strip()
        key = (source_type, sku, field)
        if key in existing:
            continue
        sources.append({
            "type": source_type,
            "label": str(evidence.get("source_label") or _display_source_label(source_type)).strip(),
            "sku": sku,
            **({"field": field} if field else {}),
        })
        existing.add(key)
    metadata = agent_result.get("answer_metadata") if isinstance(agent_result.get("answer_metadata"), dict) else {}
    missing_field = str(metadata.get("contract_field_type") or metadata.get("evidence_field") or "").strip()
    if not sources and len(result_skus) == 1 and metadata.get("field_evidence_missing") is True and missing_field:
        sources.append({
            "type": "product_field_missing",
            "label": "同 SKU 商品资料未标注该字段",
            "sku": next(iter(result_skus)),
            "field": missing_field,
        })
    return sources


def _attach_agent_quality(agent_result: dict, question: str) -> dict:
    result = dict(agent_result)
    previous_quality = (
        result.get("agent_quality")
        if isinstance(result.get("agent_quality"), dict)
        else {}
    )
    # Some semantic executors score an intermediate result before the final
    # presentation pass aligns variant/base SKU identities and evidence.  Do
    # not carry a quality warning from that intermediate envelope into the
    # public response: quality is a property of the final answer packet.  The
    # existing quality-derived warnings are removed only for this recompute;
    # upstream retrieval/tool warnings remain intact.
    previous_quality_risks = {
        str(risk or "").strip()
        for risk in (previous_quality.get("risks") or [])
        if str(risk or "").strip()
    }
    if previous_quality_risks:
        result["warnings"] = [
            warning
            for warning in (result.get("warnings") or [])
            if str(warning or "").strip() not in previous_quality_risks
        ]
    result["sources"] = _project_evidence_sources(result)
    quality = customer_agent_quality_service.evaluate_agent_response(
        question,
        answer=result.get("answer") or "",
        intent=result.get("intent") or "",
        results=result.get("results") or [],
        sources=result.get("sources") or [],
        actions=result.get("actions") or [],
        warnings=result.get("warnings") or [],
        needs_clarification=bool(result.get("needs_clarification")),
        direct_answer=not bool(result.get("sources") or result.get("actions") or result.get("results")),
        tool_results=(result.get("debug") or {}).get("tool_results") or [],
    )
    result["agent_quality"] = quality
    debug = dict(result.get("debug") or {})
    debug["agent_quality"] = quality
    debug["agent_quality_recomputed_from_final_packet"] = bool(previous_quality)
    result["debug"] = debug
    if quality.get("level") == "low":
        result["confidence"] = "low"
    elif not quality.get("passed") and result.get("confidence") == "high":
        result["confidence"] = "medium"
    elif (
        previous_quality
        and quality.get("level") == "high"
        and quality.get("passed") is True
        and not result.get("needs_clarification")
    ):
        # The earlier quality pass may already have downgraded these public
        # fields.  Restore the final packet's resolved state only when the
        # final, non-clarification answer is actually high quality.
        result["confidence"] = "high"
        if result.get("uncertainty") == "insufficient_data" and not result.get("warnings"):
            result["uncertainty"] = "resolved"
    if quality.get("risks"):
        result["warnings"] = list(dict.fromkeys([*(result.get("warnings") or []), *quality["risks"]]))
        result["debug"]["warnings"] = result["warnings"]
    return result


def _review_quality_summary(items: list[dict]) -> dict:
    scores = []
    levels: dict[str, int] = {}
    risks: dict[str, int] = {}
    for item in items:
        quality = item.get("agent_quality") or {}
        if quality.get("score") is not None:
            scores.append(float(quality.get("score") or 0))
        level = str(quality.get("level") or "unknown")
        levels[level] = levels.get(level, 0) + 1
        for risk in quality.get("risks") or []:
            key = str(risk).split(":", 1)[0]
            risks[key] = risks.get(key, 0) + 1
    top_risks = sorted(risks.items(), key=lambda item: item[1], reverse=True)[:8]
    return {
        "avg_score": round(sum(scores) / max(len(scores), 1), 3) if scores else None,
        "levels": levels,
        "top_risks": [{"risk": risk, "count": count} for risk, count in top_risks],
    }


async def _polish_customer_answer(db: Session, question: str, agent_result: dict) -> str:
    answer = str(agent_result.get("answer") or "").strip()
    if not answer or agent_result.get("answer_type") == "action_proposal":
        return answer
    answer_metadata = agent_result.get("answer_metadata") if isinstance(agent_result.get("answer_metadata"), dict) else {}
    if answer_metadata.get("evidence_insufficient") is True or answer_metadata.get("answer_policy") == "insufficient_evidence":
        return answer
    evidence = agent_result.get("evidence") or []
    if not evidence and agent_result.get("uncertainty") == "confirmed":
        return answer
    payload = {
        "question": question,
        "draft_answer": answer,
        "uncertainty": agent_result.get("uncertainty"),
        "evidence": evidence[:8],
        "followups": (agent_result.get("followups") or agent_result.get("suggested_followups") or [])[:3],
    }
    system = (
        "你是亲切、简洁的产品客服话术润色器。只能依据输入的 draft_answer、evidence、uncertainty 和 followups 改写，"
        "不得新增事实、参数、认证、价格、库存或承诺。"
        "如果 uncertainty 不是 confirmed，必须保留“资料未标注/不能确认/需要人工确认”的含义。"
        "如果 draft_answer 已经明确表达“当前知识库没有维护/现有资料不足以确认”，不要改写成产品列表、规格介绍或新的结论。"
        "如果输入内容是在回答“能不能承诺/能不能宣传/有没有禁用话术”这一类问题，且 evidence 里没有专门的负向或限制性资料，不要把正向卖点改写成禁用内容；应继续保留资料不足或未维护的结论。"
        "只输出一句简短、自然的客服承接语，不要改写、总结、复述或截取 draft_answer；系统会在你的承接语后原样附上已验证正文。"
        "承接语不得包含任何产品事实、参数、适用性、结论或承诺，也不要寒暄堆砌。"
        "输出纯中文承接语，不要输出 JSON，不要出现意图、置信度、Agent、调试、异常提示等工程词。"
        "不要逐字分析或引用用户问题中的措辞（如人数、场景词），用户问题只提供上下文。"
    )
    try:
        polished = await customer_llm_service.chat_completion(
            db,
            messages=[
                {"role": "system", "content": system},
                {"role": "user", "content": json.dumps(payload, ensure_ascii=False, default=str)},
            ],
            temperature=0.2,
            max_tokens=800,
            purpose="evidence_bounded_customer_polish",
        )
    except Exception:
        return answer
    friendly_lead = str(polished or "").strip()
    if not friendly_lead:
        return answer
    forbidden = ("意图", "置信度", "Agent", "执行过程", "异常提示")
    if any(item in friendly_lead for item in forbidden):
        return answer
    if not _is_nonduplicative_customer_lead(friendly_lead, answer):
        return answer
    if agent_result.get("uncertainty") not in {"confirmed", "resolved"} and not any(item in friendly_lead for item in ("未标注", "不能确认", "人工确认", "资料不足", "暂不能确认")):
        return answer
    rendered = f"{friendly_lead}\n{answer}"
    if not await _polished_answer_is_evidence_grounded(db, question, answer, rendered, evidence):
        return answer
    return rendered


async def _semantic_render_structured_usage_answer(
    db: Session,
    *,
    question: str,
    agent_result: dict,
    semantic_preplan: dict | None = None,
) -> dict:
    """Turn a broad same-SKU usage field into a relevant customer answer.

    Product usage columns sometimes contain guidance for several components.
    The semantic model may omit unrelated clauses, but both product identity
    and every remaining fact must stay inside the already sealed evidence.
    """
    if not isinstance(agent_result, dict):
        return agent_result
    metadata = (
        agent_result.get("answer_metadata")
        if isinstance(agent_result.get("answer_metadata"), dict)
        else {}
    )
    if not (
        isinstance(semantic_preplan, dict)
        and semantic_preplan.get("called")
        and not str(semantic_preplan.get("fallback_reason") or "").strip()
        and str(metadata.get("contract_field_type") or "").strip() == "usage_instruction"
        and str(metadata.get("evidence_status") or "").strip() == "structured"
        and str(metadata.get("evidence_source") or "").strip() == "specs.usage_instruction"
        and str(metadata.get("evidence_value") or "").strip()
        and len(agent_result.get("result_skus") or []) == 1
    ):
        return agent_result

    rows = [row for row in (agent_result.get("results") or []) if isinstance(row, dict)]
    row = rows[0] if rows else {}
    payload = {
        "question": str(question or "").strip(),
        "product": {
            "sku": str((agent_result.get("result_skus") or [""])[0]),
            "name": str(row.get("product_name_cn") or row.get("product_name_en") or "").strip(),
        },
        "evidence": str(metadata.get("evidence_value") or "").strip(),
    }

    def reject_unusable_usage_evidence() -> dict:
        product_name = str(payload["product"].get("name") or "该商品").strip()
        product_sku = str(payload["product"].get("sku") or "").strip()
        product_label = f"{product_name}（{product_sku}）" if product_sku else product_name
        agent_result["answer"] = (
            f"{product_label}：现有同 SKU 使用说明无法形成与这个问题直接对应、可核验的完整操作步骤，"
            "暂不建议把这段资料当作首次操作指南；请以该型号说明书或人工核对结果为准。"
        )
        metadata["semantic_usage_rendered"] = False
        metadata["semantic_usage_rejected"] = True
        metadata["semantic_usage_renderer_model"] = str(
            customer_agent_planner_service._semantic_preplan_runtime_settings().get("model") or ""
        )
        metadata["evidence_status"] = "insufficient"
        agent_result["answer_metadata"] = metadata
        debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
        debug["semantic_usage_rejected"] = True
        agent_result["debug"] = debug
        agent_result["skip_polish"] = True
        return agent_result

    runtime = customer_agent_planner_service._semantic_preplan_runtime_settings()
    try:
        raw = await customer_llm_service.chat_completion(
            db,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "你是产品客服回答编辑器。只根据输入的同一商品使用说明回答客户当前问题。"
                        "提取与当前问题和该商品直接相关的步骤，删除其他器具、其他组件或无关场景的说明。"
                        "只保留写清楚动作和对象、客户能直接照做的步骤。省略笼统、循环或无法执行的句子；"
                        "例如证据只说“根据场景采用相应方法”时，必须说明资料没有给出具体方法，不能复述该句；"
                        "如果删去后步骤不完整，应直接指出现有资料还缺哪些操作细节。"
                        "不得补充常识、推测步骤、参数或安全承诺；证据没有写明的细节要明确说资料未写明。"
                        "只输出 JSON：{\"confirmed_actions\":[\"证据直接支持的具体动作\"],"
                        "\"missing_details\":\"证据缺少的操作细节\"}。"
                        "confirmed_actions 中每项都必须有具体动作和对象，不得放入空泛指令；没有则返回空数组。"
                    ),
                },
                {"role": "user", "content": json.dumps(payload, ensure_ascii=False)},
            ],
            temperature=0,
            max_tokens=320,
            purpose="structured_usage_relevance_render",
            api_model_override=runtime["model"],
            response_format=runtime["response_format"],
            thinking=runtime["thinking"],
        )
        rendered = customer_agent_planner_service._extract_json_object(str(raw or "")) or {}
        confirmed_actions = [
            str(item or "").strip().rstrip("。")
            for item in (rendered.get("confirmed_actions") or [])
            if str(item or "").strip()
        ]
        missing_details = str(rendered.get("missing_details") or "").strip().rstrip("。")
        # The JSON field already means “what the evidence does not state”.
        # Providers sometimes repeat that frame inside the value itself;
        # normalize it before adding the fixed customer-facing lead.
        missing_details = re.sub(
            r"^(?:(?:现有)?资料(?:中)?未(?:明确)?写明|未(?:明确)?写明)\s*[：:]?\s*",
            "",
            missing_details,
        ).strip()
        if not confirmed_actions and not missing_details:
            return reject_unusable_usage_evidence()
        product_name = str(payload["product"].get("name") or "该商品").strip()
        product_sku = str(payload["product"].get("sku") or "").strip()
        product_label = f"{product_name}（{product_sku}）" if product_sku else product_name
        answer_parts = []
        if confirmed_actions:
            answer_parts.append(f"{product_label}根据现有使用说明可确认：{'；'.join(confirmed_actions)}。")
        if missing_details:
            answer_parts.append(f"现有资料未写明{missing_details}。")
        candidate = "".join(answer_parts)
        verification_raw = await customer_llm_service.chat_completion(
            db,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "只输出 JSON：{\"grounded\":true或false,\"relevant\":true或false,\"vague\":true或false}。"
                        "grounded 仅在答案每个产品事实和步骤都可由 evidence 直接推出时为 true；"
                        "relevant 仅在答案直接回应 question 且没有混入其他器具、组件或无关说明时为 true。"
                        "如果答案把“按相应方式操作”“遵循对应方法”等没有具体动作和对象的循环表述当作步骤，"
                        "或者只是换一种说法复述这种空泛指令，vague 必须为 true 且 relevant 必须为 false。"
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps({**payload, "candidate_answer": candidate}, ensure_ascii=False),
                },
            ],
            temperature=0,
            max_tokens=80,
            purpose="structured_usage_relevance_verify",
            api_model_override=runtime["model"],
            response_format=runtime["response_format"],
            thinking=runtime["thinking"],
        )
    except Exception:
        return reject_unusable_usage_evidence()
    verdict = customer_agent_planner_service._extract_json_object(str(verification_raw or "")) or {}
    if (
        verdict.get("grounded") is not True
        or verdict.get("relevant") is not True
        or verdict.get("vague") is not False
    ):
        return reject_unusable_usage_evidence()
    agent_result["answer"] = candidate
    metadata["semantic_usage_rendered"] = True
    metadata["semantic_usage_renderer_model"] = str(runtime.get("model") or "")
    agent_result["answer_metadata"] = metadata
    debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
    debug["semantic_usage_rendered"] = True
    agent_result["debug"] = debug
    agent_result["skip_polish"] = True
    return agent_result


def _is_nonduplicative_customer_lead(lead: str, draft_answer: str) -> bool:
    """Accept only a fact-free lead instead of echoing the verified body.

    This is a presentation guard after semantic routing, entity sealing and
    grounding have completed.  It does not classify customer intent or alter
    facts: if a style model repeats any meaningful body fragment, preserve the
    original verified answer rather than render it twice.
    """
    normalized_lead = re.sub(r"[\W_]+", "", str(lead or "").casefold())
    normalized_body = re.sub(r"[\W_]+", "", str(draft_answer or "").casefold())
    if not normalized_lead:
        return False
    window = 6
    if len(normalized_lead) < window or len(normalized_body) < window:
        return True
    return not any(
        normalized_lead[index:index + window] in normalized_body
        for index in range(len(normalized_lead) - window + 1)
    )


async def _polished_answer_is_evidence_grounded(
    db: Session,
    question: str,
    draft_answer: str,
    polished_answer: str,
    evidence: list[dict],
) -> bool:
    """Let the model reject a polish that exceeds the sealed evidence packet."""
    semantic_runtime = customer_agent_planner_service._semantic_preplan_runtime_settings()
    try:
        raw = await customer_llm_service.chat_completion(
            db,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Return only JSON: {grounded:boolean}. Return true only when polished_answer preserves the factual scope "
                        "of draft_answer and the supplied evidence. Return false if it adds, removes, changes, summarises, generalises, or strengthens any product fact, "
                        "parameter, promise, suitability conclusion, safety instruction, or uncertainty."
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps(
                        {
                            "question": question,
                            "draft_answer": draft_answer,
                            "polished_answer": polished_answer,
                            "evidence": evidence[:8],
                        },
                        ensure_ascii=False,
                        default=str,
                    ),
                },
            ],
            temperature=0,
            max_tokens=80,
            purpose="evidence_bounded_customer_polish_grounding",
            api_model_override=semantic_runtime["model"],
            response_format=semantic_runtime["response_format"],
            thinking=semantic_runtime["thinking"],
        )
    except Exception:
        return False
    verdict = customer_agent_planner_service._extract_json_object(str(raw or "")) or {}
    return verdict.get("grounded") is True


def _should_skip_polish_for_agent_result(agent_result: dict) -> bool:
    answer_type = str(agent_result.get("answer_type") or "").strip().lower()
    intent = str(agent_result.get("intent") or "").strip().lower()
    results = agent_result.get("results") or []
    warnings = agent_result.get("warnings") or []
    sources = agent_result.get("sources") or []

    # Product answers already come from a sealed QA/RAG or structured-evidence
    # path.  A second style LLM used to prepend generic formal language (and
    # occasionally weaken the customer's direct answer).  Keep the verified
    # body as-is; presentation must not become another answer owner.
    if answer_type in {"faq", "product_usage_care", "recommendation", "comparison", "clarification", "product_detail", "knowledge_base_answer"}:
        return True

    if _is_evidence_bounded_single_product_answer(agent_result):
        return False

    if intent in {"purchase_channel", "aftersales", "company_info", "greeting", "product_usage_care", "recommend_products", "compare_products", "clarify", "product_detail"}:
        return True
    if answer_type == "product_query" and not results:
        return True
    if answer_type == "product_query" and any(source.get("type") == "product_qa" for source in sources if isinstance(source, dict)):
        return True
    if "missing_product_results" in warnings:
        return True
    return False


def _is_evidence_bounded_single_product_answer(agent_result: dict) -> bool:
    """Allow style-only rendering after identity and evidence are already sealed."""
    if str(agent_result.get("uncertainty") or "").strip() not in {"confirmed", "resolved"}:
        return False
    metadata = agent_result.get("answer_metadata") if isinstance(agent_result.get("answer_metadata"), dict) else {}
    if metadata.get("evidence_status") != "matched" or metadata.get("field_evidence_missing") is True:
        return False
    result_skus = [str(item or "").strip().upper() for item in agent_result.get("result_skus") or [] if str(item or "").strip()]
    if len(result_skus) != 1:
        return False
    debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
    contract = debug.get("entity_resolution_contract") if isinstance(debug.get("entity_resolution_contract"), dict) else {}
    if contract.get("status") != "resolved" or str(contract.get("resolved_sku") or "").strip().upper() != result_skus[0]:
        return False
    evidence = [item for item in agent_result.get("evidence") or [] if isinstance(item, dict)]
    return bool(evidence) and all(str(item.get("sku") or "").strip().upper() == result_skus[0] for item in evidence)


_FINAL_SOURCE_PRIORITY = {
    "product_usage_care": 1,
    "customer_faq": 2,
    "product_qa": 3,
    "structured_product_detail": 3,
    "knowledge_chunks": 4,
    "query_products": 5,
    "llm_fallback": 6,
}


def _pick_primary_answer_source(agent_result: dict) -> dict:
    intent = str(agent_result.get("intent") or "").strip().lower()
    answer_type = str(agent_result.get("answer_type") or "").strip().lower()
    sources = agent_result.get("sources") or []

    if intent == "product_usage_care" or answer_type == "product_usage_care":
        return {"type": "product_usage_care", "priority": 1}
    if answer_type == "faq" or intent in {"purchase_channel", "aftersales", "company_info", "greeting"}:
        return {"type": "customer_faq", "priority": 2}
    if answer_type in {"product_detail", "comparison"}:
        return {"type": "structured_product_detail", "priority": 3}
    if answer_type == "recommendation" and (agent_result.get("results") or []):
        return {"type": "query_products", "priority": 5}
    if (intent == "query_products" or answer_type == "product_query") and (agent_result.get("results") or []):
        return {"type": "query_products", "priority": 5}
    if answer_type == "knowledge_base_answer":
        return {"type": "knowledge_chunks", "priority": 4}
    if any(isinstance(source, dict) and source.get("type") == "product_qa" for source in sources):
        return {"type": "product_qa", "priority": 3}
    if any(isinstance(source, dict) and source.get("type") in {"knowledge_base", "usage_care_knowledge", "faq_knowledge"} for source in sources):
        return {"type": "knowledge_chunks", "priority": 4}
    if intent == "query_products" or answer_type == "product_query":
        return {"type": "query_products", "priority": 5}
    return {"type": "llm_fallback", "priority": 6}


def _tag_and_order_sources(sources: list[dict], primary: dict) -> list[dict]:
    tagged: list[dict] = []
    for source in sources:
        if not isinstance(source, dict):
            continue
        item = dict(source)
        item["role"] = "primary" if _source_matches_primary(item, primary.get("type")) else "supporting"
        tagged.append(item)
    tagged.sort(key=lambda item: 0 if item.get("role") == "primary" else 1)
    return tagged


def _source_matches_primary(source: dict, primary_type: str | None) -> bool:
    source_type = str(source.get("type") or "").strip().lower()
    if primary_type == "product_usage_care":
        return source_type in {"product_qa", "usage_care_knowledge"}
    if primary_type == "customer_faq":
        return source_type in {"faq", "structured_faq", "faq_knowledge"}
    if primary_type == "product_qa":
        return source_type == "product_qa"
    if primary_type == "structured_product_detail":
        return source_type in {"product", "product_compare", "product_search"}
    if primary_type == "knowledge_chunks":
        return source_type in {"knowledge_base", "usage_care_knowledge", "faq_knowledge"}
    if primary_type == "query_products":
        return source_type == "product_search"
    if primary_type == "llm_fallback":
        return source_type == "agent_meta"
    return False


def _llm_allowed_for_final_answer(agent_result: dict, primary: dict) -> bool:
    # This is a style-only pass after a resolved EntityResolutionContract and
    # same-SKU evidence have been sealed. It does not authorize the model to
    # select a product, field, or fact.
    if _is_evidence_bounded_single_product_answer(agent_result):
        return True
    primary_type = primary.get("type")
    if primary_type in {"product_usage_care", "customer_faq", "product_qa", "structured_product_detail", "knowledge_chunks"}:
        return False
    if primary_type == "query_products" and (agent_result.get("results") or agent_result.get("sources")):
        return False
    return primary_type == "llm_fallback"


def _sanitize_final_answer_text(answer: str, primary: dict) -> str:
    text = str(answer or "").strip()
    if not text:
        return text
    # A clarification generated before the dialogue context is resolved can
    # contain internal orchestration wording.  Keep the customer action, but
    # remove references to turns/results that are not meaningful to a shopper.
    text = re.sub(
        r"你(?:说的|提到的)[“\"]?这些[”\"]?(?:我还没有可引用的上一轮商品结果|目前没有可引用的上一轮结果)[。！!]?\s*",
        "",
        text,
    )
    text = re.sub(
        r"我还没有可引用的上一轮商品结果[。！!]?\s*",
        "",
        text,
    )
    text = re.sub(
        r"你提到的[“\"]?这些[”\"]?目前没有可引用的上一轮结果[。！!]?\s*",
        "",
        text,
    )
    text = re.sub(r"上一轮商品结果|上一轮结果|可引用的上一轮", "此前商品信息", text)
    text = text.replace("上一轮", "前面")
    # Imported catalogue rows can contain search-index and listing-title
    # metadata in an otherwise customer-facing field list. Preserve adjacent
    # product facts, but remove each internal metadata segment in full.
    text = re.sub(
        r"(?:^|[；;\n])\s*(?:关键词库|中文标题|英文标题)\s*[:：][^；;\n]*",
        "",
        text,
        flags=re.I,
    )
    text = re.sub(
        r"(?:^|[；;\n])[^；;\n]*(?:keyword|priority)\s*[:：][^；;\n]*",
        "",
        text,
        flags=re.I,
    )
    # Imported product-detail rows can be accidentally rendered as a single
    # customer answer.  Remove the internal label block (especially owner and
    # lifecycle fields) while preserving a genuine customer-facing conclusion
    # that follows it.
    # A natural comparison can legitimately mention two SKUs and a few
    # customer-facing fields.  The former ``label_count >= 3`` heuristic
    # treated that normal prose as an imported row and replaced it with a
    # generic missing-answer sentence.  Only high-signal catalogue metadata
    # should enter this cleanup path; ordinary SKU/field mentions are not a
    # product dump by themselves.
    high_signal_internal_labels = (
        "负责人", "生命周期", "产品资料", "内容信息", "中文标题", "英文标题",
        "中文描述", "英文描述", "业务信息",
    )
    high_signal_label_count = sum(
        1
        for label in high_signal_internal_labels
        if re.search(rf"(?:^|[\n；;：:\-])\s*{re.escape(label)}\s*[:：]", text, flags=re.I)
    )
    compact_product_dump = sum(
        1
        for label in ("内容信息", "中文标题", "英文标题", "中文描述", "英文描述")
        if re.search(rf"{re.escape(label)}\s*[:：]", text, flags=re.I)
    ) >= 2
    if compact_product_dump or high_signal_label_count >= 2 or (
        re.search(r"(?:^|[\n；;])\s*负责人\s*[:：]", text)
        and re.search(r"(?:^|[\n；;])\s*SKU\s*[:：]", text, flags=re.I)
    ):
        lines = [line.strip() for line in text.splitlines() if line.strip()]
        customer_heading = re.compile(
            r"^(?:兼容性结论|处理建议|注意事项|安全提醒|配件结论|存放结论|先说结论|结论)\s*[:：]"
        )
        tail_index = next((index for index, line in enumerate(lines) if customer_heading.search(line)), None)
        if tail_index is not None:
            text = "\n".join(lines[tail_index:])
        else:
            inline_heading = re.search(
                r"(?:兼容性结论|处理建议|注意事项|安全提醒|配件结论|存放结论|先说结论|结论)\s*[:：]",
                text,
            )
            # Do not turn a false-positive cleanup into a canned evidence
            # refusal.  Keep the original customer prose when no explicit
            # customer conclusion heading exists; the semantic writer is the
            # owner of the answer and this function only removes proven
            # internal metadata blocks.
            text = text[inline_heading.start():] if inline_heading else text
    # Evidence provenance remains in API metadata.  Field paths are internal
    # implementation details and make a customer-facing answer look like a
    # debug trace when an upstream renderer includes them.
    internal_path = r"(?:content|specs|business|product|answer_metadata|debug)(?:\.[A-Za-z_][A-Za-z0-9_]*)+"
    text = re.sub(
        rf"[（(]\s*来源\s*[:：]\s*{internal_path}\s*[）)]",
        "",
        text,
        flags=re.I,
    )
    text = re.sub(rf"\b{internal_path}\b", "相关商品资料", text, flags=re.I)
    # Product-detail renderers may append provenance markers intended for
    # internal review (for example ``（补充资料）`` and a QA/KB field note).
    # The evidence remains available in structured API metadata; remove the
    # implementation-source wording from the customer-visible answer.
    text = re.sub(r"[（(]\s*补充资料\s*[）)]", "", text)
    text = re.sub(
        r"依据：以上字段已结合当前 SKU 的\s*QA\s*/\s*KB\s*补充资料。?",
        "",
        text,
        flags=re.I,
    )
    # Keep provenance useful without exposing the internal renderer's source
    # label.  Phrases such as “依据产品资料” are not a product fact and read
    # like backend metadata in a customer-facing answer.
    text = re.sub(r"依据\s*(?:来自\s*)?产品资料", "根据已核对信息", text)
    text = re.sub(r"依据\s*(?:是|来自)\s*产品资料", "根据已核对信息", text)
    text = re.sub(r"产品资料\s*，", "已核对信息，", text)
    text = re.sub(r"产品资料\s*明确标注", "已核对信息明确标注", text)
    text = re.sub(r"产品资料\s*中", "已核对信息中", text)
    # Structured catalogue fallbacks used implementation labels that are
    # meaningful to an operator but not to a shopper.  Keep the conclusion
    # and the requested condition while removing the backend vocabulary.
    text = re.sub(r"结构化商品库", "已核对资料", text)
    text = re.sub(
        r"查询类目\s*[:：]\s*[【\[]?(?P<category>[^；;。\n】\]]+)[】\]]?\s*[；;]\s*",
        lambda match: f"类别为“{match.group('category').strip()}”；",
        text,
    )
    text = re.sub(r"同\s*SKU\s*的已验证资料作为筛选条件", "同一款商品资料同时核对这些要求", text)
    # Same-SKU sealing is an internal evidence guarantee, not useful shopping
    # language. Keep the facts while removing duplicated provenance tails and
    # translating any remaining ownership wording into ordinary customer prose.
    text = re.sub(r"；\s*同\s*SKU\s*资料\s*[:：]", "；关键参数：", text, flags=re.I)
    text = re.sub(r"适用热源\s*/\s*同\s*SKU\s*证据\s*为\s*[:：]", "商品资料写明：", text, flags=re.I)
    text = re.sub(r"按已核验的同\s*SKU\s*资料", "根据已核对的商品资料", text, flags=re.I)
    text = re.sub(r"同\s*SKU\s*热源信息", "商品热源资料", text, flags=re.I)
    text = re.sub(r"同\s*SKU\s*资料", "该商品资料", text, flags=re.I)
    text = re.sub(r"同\s*SKU\s*证据", "该商品资料", text, flags=re.I)
    text = re.sub(r"放宽筛选条件", "放宽部分要求", text)
    text = re.sub(r"筛选条件\s*[:：]\s*", "按你的条件：", text)
    # Any residual operator phrasing should still read as ordinary customer
    # language when it comes from a fallback assembled elsewhere.
    text = text.replace("筛选条件", "要求")
    text = re.sub(r"结构化硬筛选条件", "已核对条件", text)
    text = re.sub(r"[“\"]类目[”\"]\s*(?:明确)?(?:标注|标明)为", "类别是", text)
    text = re.sub(r"类目\s*(?:明确)?(?:标注|标明)为", "类别是", text)
    # The runtime and imported QA prompts use “知识库/数据库/字段/系统里”
    # as internal provenance language.  It must never leak into the answer
    # shown to a customer; preserve the underlying uncertainty while using
    # the neutral customer-facing term “当前资料/信息”.
    text = re.sub(r"(?:当前|现有|本次)?知识库", "当前资料", text)
    text = re.sub(r"数据库商品类目字段", "商品目录", text)
    text = re.sub(r"数据库", "商品资料", text)
    text = re.sub(r"系统里记录(?:的)?", "目前可核对到的", text)
    text = re.sub(r"系统里", "当前资料里", text)
    text = re.sub(r"(?:当前|现有|结构化|商品资料|商品库)\s*字段", "信息", text)
    text = re.sub(r"(?:该|这个|此)字段", "该信息", text)
    text = re.sub(r"字段(确认|里|中)", r"信息\1", text)
    # A renderer can also prepend a field's human label (for example
    # “热源字段” or “容量字段”), which is still implementation language even
    # though it does not match the longer provenance patterns above.
    text = re.sub(r"字段", "信息", text)
    # Some imported QA/listing snippets contain a bare ORM field name without
    # its dotted path.  That is still an internal implementation label and
    # must not be shown to customers.
    bare_internal_fields = {
        "heat_source": "适用热源",
        "body_material": "主体材质",
        "surface_finish": "表面处理",
        "gross_weight_g": "重量",
        "size_info": "尺寸信息",
        "usage_scenarios": "适用场景",
        "target_audience": "适用人群",
        "technical_advantages": "技术特点",
        "top_selling_points": "主要卖点",
        "person_in_charge": "负责人资料",
        "subject_subtype": "商品类型",
        "subject_kind": "商品类型",
        "recommendation_contract": "推荐条件",
        "semantic_constraints": "推荐条件",
        "verified_constraints": "已核对条件",
        "evidence_usage": "依据",
    }
    for field_name, label in bare_internal_fields.items():
        text = re.sub(rf"(?<![A-Za-z0-9_]){re.escape(field_name)}(?![A-Za-z0-9_])", label, text, flags=re.I)
    # LLM/tool renderers occasionally stringify a list-valued catalogue field
    # into Python/JSON syntax.  Convert a closed literal list to ordinary
    # customer prose instead of exposing brackets and quoted debug values.
    def _replace_inline_literal_list(match: re.Match) -> str:
        raw = str(match.group(0) or "")[1:-1]
        values = [item.strip().strip("'\"") for item in re.split(r"\s*,\s*", raw) if item.strip()]
        return "、".join(values)

    text = re.sub(
        r"\[(?:\s*(?:\"[^\n\"]*\"|'[^\n']*')(?:\s*,\s*(?:\"[^\n\"]*\"|'[^\n']*'))*)\s*\]",
        _replace_inline_literal_list,
        text,
    )
    # Owner/lifecycle fields are operational metadata, not customer-facing
    # product facts.  Remove an inline sentence even when it was not rendered
    # as a labelled dump block.
    # Owner names are operational metadata.  Replace the whole label/name
    # span with a customer-facing support contact instead of exposing staff
    # identities (for example, “联系负责人 Greta”).
    text = re.sub(
        r"负责人\s*(?:为|是)?\s*[A-Za-z][A-Za-z0-9_\-]*",
        "店铺客服",
        text,
        flags=re.I,
    )
    text = re.sub(r"负责人", "店铺客服", text)
    # Customer output is plain text in the service UI.  Strip Markdown control
    # markers that otherwise render as noisy literal asterisks/backticks when
    # an upstream model returns formatted prose.
    text = text.replace("**", "").replace("```", "").replace("`", "")
    text = re.sub(r"(^|\n)\s*#{1,6}\s*", r"\1", text)
    text = re.sub(r"[ \t]{2,}", " ", text)
    text = re.sub(r"(^|\n)\s*Q:\s*", r"\1", text, flags=re.I)
    text = re.sub(r"(^|\n)\s*A:\s*", r"\1", text, flags=re.I)
    text = re.sub(r"\n{3,}", "\n\n", text).strip()
    return text


def _answer_type_from_intent(intent: str | None) -> str:
    return {
        "query_products": "product_query",
        "product_detail": "product_detail",
        "compare_products": "comparison",
        "recommend_products": "recommendation",
        "propose_delete": "action_proposal",
        "propose_update": "action_proposal",
        "clarify": "clarification",
    }.get(str(intent or ""), "unknown")


def _uncertainty_from_answer(answer: str, results: list, warnings: list, needs_clarification: bool) -> str:
    if needs_clarification:
        return "ambiguous_product"
    if any(item in answer for item in ("没有标注", "不能直接确认", "暂时不能确认", "资料未标注")):
        return "not_recorded"
    if not results and any(item in answer for item in ("没有找到", "暂时无法", "不能可靠")):
        return "insufficient_data"
    if warnings:
        return "insufficient_data"
    return "confirmed"


def _result_evidence_display_value(field_label: str, value: Any) -> str:
    """Apply structured-value validation before result evidence reaches the API."""
    canonical_field = {
        "容量": "capacity",
        "材质": "material",
        "颜色": "color",
        "类目": "category",
        "卖点": "selling_point",
    }.get(str(field_label or "").strip(), str(field_label or "").strip())
    return _phase1_comparison_evidence_value(canonical_field, value)


def _evidence_from_results(results: list) -> list[dict]:
    evidence = []
    for item in results[:8]:
        if not isinstance(item, dict):
            continue
        field_values = item.get("field_values") if isinstance(item.get("field_values"), dict) else {}
        if field_values:
            for label, value in field_values.items():
                if str(label or "").strip() in {"负责人", "品质情况", "备注"}:
                    continue
                display_value = _result_evidence_display_value(str(label), value)
                if not display_value:
                    continue
                evidence.append({
                    "sku": item.get("sku"),
                    "product_name": item.get("product_name_cn") or item.get("product_name_en"),
                    "field_label": label,
                    "value": display_value,
                    "source_layer": _layer_for_field_label(str(label)),
                    "matched_by": item.get("matched_by") or "产品资料",
                })
            continue
        for label, key in (("容量", "capacity"), ("材质", "body_material"), ("颜色", "color"), ("类目", "category"), ("卖点", "features")):
            value = item.get(key)
            display_value = _result_evidence_display_value(label, value)
            if display_value:
                evidence.append({
                    "sku": item.get("sku"),
                    "product_name": item.get("product_name_cn") or item.get("product_name_en"),
                    "field_label": label,
                    "value": display_value,
                    "source_layer": _layer_for_field_label(label),
                    "matched_by": item.get("matched_by") or "产品资料",
                })
    return evidence


def _layer_for_field_label(label: str) -> str:
    if any(item in label for item in ("容量", "重量", "材质", "颜色", "热源", "功率", "表面")):
        return "L2"
    if any(item in label for item in ("卖点", "场景", "定位", "人群", "竞品")):
        return "L3"
    if any(item in label for item in ("标题", "描述", "关键词", "listing", "Listing")):
        return "L4"
    return "L1"









def _latest_persisted_agent_context_sku(db: Session, conversation_id: str | None) -> str:
    if not conversation_id:
        return ""
    message = db.query(CustomerServiceMessage).filter(
        CustomerServiceMessage.conversation_id == conversation_id,
        CustomerServiceMessage.role == "assistant",
    ).order_by(CustomerServiceMessage.created_at.desc(), CustomerServiceMessage.id.desc()).first()
    if message is None:
        return ""
    sources = _safe_json(message.sources_json, [])
    for source in sources:
        if not isinstance(source, dict) or source.get("type") != "agent_context":
            continue
        result_skus = [
            str(value or "").strip().upper()
            for value in (source.get("result_skus") or [])
            if str(value or "").strip()
        ]
        if len(result_skus) != 1:
            continue
        sku = str(source.get("current_sku") or "").strip().upper()
        if sku:
            return sku
        if len(result_skus) == 1:
            return result_skus[0]
    # Older and deterministic result paths persist first-party product
    # evidence but not a dedicated agent_context entry. A single distinct SKU
    # on the immediately preceding assistant turn is still a sealed identity;
    # multiple SKUs remain deliberately ambiguous.
    evidence_skus = {
        str(source.get("sku") or "").strip().upper()
        for source in sources
        if isinstance(source, dict)
        and str(source.get("sku") or "").strip()
        and source.get("type") in {"product_db", "product_field", "knowledge_qa", "knowledge_document"}
    }
    if len(evidence_skus) == 1:
        return next(iter(evidence_skus))
    return ""


def _latest_active_product_skus(db: Session, conversation_id: str | None, user_id: str) -> list[str]:
    if not conversation_id:
        return []
    conversation = db.query(CustomerServiceConversation).filter(
        CustomerServiceConversation.id == conversation_id,
        CustomerServiceConversation.user_id == str(user_id),
    ).first()
    if not conversation:
        return []
    messages = db.query(CustomerServiceMessage).filter(
        CustomerServiceMessage.conversation_id == conversation_id,
        CustomerServiceMessage.role == "assistant",
    ).order_by(CustomerServiceMessage.created_at.desc(), CustomerServiceMessage.id.desc()).limit(5).all()
    for message in messages:
        for source in _safe_json(message.sources_json, []):
            if not isinstance(source, dict) or source.get("type") != "agent_context":
                continue
            current_sku = str(source.get("current_sku") or "").strip().upper()
            if current_sku:
                return [current_sku]
            entities = [item for item in (source.get("entities") or []) if isinstance(item, dict)]
            current_entities = [
                str(item.get("sku") or "").strip().upper()
                for item in entities
                if str(item.get("role") or "") == "current" and str(item.get("sku") or "").strip()
            ]
            if len(current_entities) == 1:
                return current_entities
            result_skus = [
                str(sku or "").strip().upper()
                for sku in (source.get("result_skus") or [])
                if str(sku or "").strip()
            ]
            if len(result_skus) == 1:
                return result_skus
        sku = str(message.sku or "").strip().upper()
        if sku:
            return [sku]
        primary_sku = _primary_sku_from_message_content(message.content)
        if primary_sku:
            return [primary_sku]
    return []


def _latest_ordered_result_skus_for_followup(db: Session, conversation_id: str | None, user_id: str) -> list[str]:
    if not conversation_id:
        return []
    conversation = db.query(CustomerServiceConversation).filter(
        CustomerServiceConversation.id == conversation_id,
        CustomerServiceConversation.user_id == str(user_id),
    ).first()
    if not conversation:
        return []
    messages = db.query(CustomerServiceMessage).filter(
        CustomerServiceMessage.conversation_id == conversation_id,
        CustomerServiceMessage.role == "assistant",
    ).order_by(CustomerServiceMessage.created_at.desc(), CustomerServiceMessage.id.desc()).limit(5).all()
    for message in messages:
        sources = _safe_json(message.sources_json, [])
        for source in sources:
            if not isinstance(source, dict):
                continue
            if source.get("type") == "agent_meta":
                for context_key in ("candidate_context", "recommendation_context"):
                    context = source.get(context_key)
                    if not isinstance(context, dict):
                        continue
                    ordered = [
                        str(sku or "").strip().upper()
                        for sku in (
                            context.get("ordered_result_skus")
                            or context.get("recommended_skus")
                            or context.get("candidate_skus")
                            or []
                        )
                        if str(sku or "").strip()
                    ]
                    if ordered:
                        return ordered
            if source.get("type") == "agent_context":
                ordered = [
                    str(sku or "").strip().upper()
                    for sku in (source.get("result_skus") or [])
                    if str(sku or "").strip()
                ]
                if ordered:
                    return ordered
    return []












def _should_keep_preruntime_for_scoped_heat_source_followup(
    question: str,
    *,
    candidate_context: dict[str, Any] | None,
) -> bool:
    text = str(question or "")
    if "酒精炉" not in text and "alcohol stove" not in text.lower():
        return False
    if not any(term in text for term in ("里面", "这些", "这几款", "这些里", "哪些", "有哪", "支持", "能用", "适合")):
        return False
    return bool((candidate_context or {}).get("candidate_skus") or (candidate_context or {}).get("ordered_result_skus"))








def _is_service_pot_or_cookware_set_candidate(row: dict[str, Any], product: Product | None = None) -> bool:
    if not isinstance(row, dict):
        return False
    row_text = " ".join(
        str(row.get(key) or "")
        for key in (
            "sku",
            "product_name_cn",
            "product_name_en",
            "name",
            "title",
            "category",
            "sub_category",
            "capacity",
            "features",
            "usage_scenarios",
            "target_audience",
            "positioning",
            "semantic_match",
            "long_description_cn",
        )
    )
    product_text = ""
    if product is not None:
        product_text = " ".join(
            str(value or "")
            for value in (
                product.product_name_cn,
                product.product_name_en,
                product.category,
                product.sub_category,
            )
        )
    text = f"{row_text} {product_text}".lower()
    category = str(row.get("category") or "").strip()
    identity_text = " ".join(
        str(row.get(key) or "")
        for key in ("product_name_cn", "product_name_en", "name", "title")
    ).lower()
    if product is not None:
        identity_text = f"{identity_text} {str(product.product_name_cn or '')} {str(product.product_name_en or '')}".lower()
    if (
        any(term in identity_text for term in ("炉", "stove", "burner"))
        and not any(term in identity_text for term in ("单锅", "套锅", "锅具套装", "炊具套装", "cookware set", "pot set"))
    ):
        return False
    # A cookware set may legitimately list a frying/griddle component beside
    # multiple pots.  Treat that as a cookware set only when the canonical
    # category and structured capacity both establish the multi-pot set; a
    # standalone griddle remains outside the cookware candidate domain.
    multi_pot_set_signature = bool(
        category == "\u9505\u5177"
        and "\u5957\u88c5" in text
        and len(re.findall(r"\d+(?:\.\d+)?\s*(?:l|ml)\s*\u9505", text, flags=re.I)) >= 2
    )
    if _is_service_pan_or_griddle_candidate_text(text) and not multi_pot_set_signature:
        return False
    accessory_terms = (
        "防刮手夹",
        "锅夹",
        "手夹",
        "夹子",
        "收纳包",
        "收纳袋",
        "配件",
        "accessory",
    )
    if any(term in text for term in accessory_terms) and not any(term in text for term in ("套锅", "单锅", "锅具套装", "炊具套装")):
        return False
    if any(term in text for term in ("炉具", "炉子", "酒精炉", "气炉", "燃气炉", "stove", "burner")):
        if not multi_pot_set_signature and not any(
            term in text for term in ("套锅", "单锅", "锅具套装", "炊具套装", "cookware set", "pot set")
        ):
            return False
    strong_cookware_terms = (
        "单锅",
        "套锅",
        "炒锅",
        "汤锅",
        "锅具套装",
        "炊具套装",
        "炊具组合",
        "野餐锅",
        "野营锅",
        "小方锅",
        "cookware set",
        "cook set",
        "pot set",
    )
    water_container_terms = ("水壶", "茶壶", "烧水壶", "kettle", "bottle", "flask", "cup", "杯")
    product_identity_text = " ".join(
        str(value or "")
        for value in (
            row.get("product_name_cn"),
            row.get("product_name_en"),
            row.get("name"),
            row.get("title"),
            product.product_name_cn if product is not None else "",
            product.product_name_en if product is not None else "",
        )
    ).lower()
    non_category_cookware_text = " ".join(
        str(value or "")
        for value in (
            row.get("product_name_cn"),
            row.get("product_name_en"),
            row.get("name"),
            row.get("title"),
            row.get("features"),
            row.get("usage_scenarios"),
            row.get("target_audience"),
            row.get("positioning"),
            row.get("long_description_cn"),
            product.product_name_cn if product is not None else "",
            product.product_name_en if product is not None else "",
            product.sub_category if product is not None else "",
        )
    ).lower()
    if not multi_pot_set_signature and any(term in text for term in ("水壶", "茶壶", "烧水壶", "kettle", "bottle", "flask", "cup", "杯")) and not any(
        term in text for term in strong_cookware_terms
    ):
        return False
    if not multi_pot_set_signature and any(term in product_identity_text for term in water_container_terms) and not any(
        term in non_category_cookware_text for term in strong_cookware_terms
    ):
        return False
    has_positive_cookware_shape = _is_service_pot_or_cookware_set_text(text)
    if not multi_pot_set_signature and any(term in text for term in ("水壶", "茶壶", "烧水壶", "kettle", "bottle", "flask", "cup", "杯")) and not has_positive_cookware_shape:
        return False
    return multi_pot_set_signature or has_positive_cookware_shape


def _is_service_pan_or_griddle_candidate_text(text: str) -> bool:
    value = str(text or "").lower()
    positive_set_terms = (
        "套锅",
        "锅具套装",
        "炊具套装",
        "炊具组合",
        "野餐锅",
        "野营锅",
        "cookware set",
        "cook set",
        "pot set",
    )
    if any(term in value for term in positive_set_terms):
        return False
    excluded_terms = (
        "煎盘",
        "烤盘",
        "煎烤盘",
        "烧烤盘",
        "griddle",
        "grill pan",
        "grill plate",
        "fry pan",
        "frying pan",
        "pan plate",
    )
    return any(term in value for term in excluded_terms)


def _is_service_pot_or_cookware_set_text(text: str) -> bool:
    value = str(text or "").lower()
    allowed_terms = (
        "单锅",
        "套锅",
        "锅具",
        "炊具",
        "炊具套装",
        "锅具套装",
        "野餐锅",
        "野营锅",
        "cookware set",
        "cook set",
        "pot set",
        " pot",
    )
    if any(term in value for term in allowed_terms):
        return True
    return "锅" in value










def _make_title(question: str, sku: str | None) -> str:
    clean = re.sub(r"\s+", " ", question).strip()
    return clean[:20] or (sku or "客服会话")




def _safe_json(value: str | None, fallback):
    if not value:
        return fallback
    try:
        return json.loads(value)
    except json.JSONDecodeError:
        return fallback






def _assistant_turn_index(db: Session, conversation_id: str) -> int:
    return db.query(CustomerServiceMessage).filter(
        CustomerServiceMessage.conversation_id == conversation_id,
        CustomerServiceMessage.role == "assistant",
    ).count()


def _primary_sku_from_message_content(content: str | None) -> str | None:
    text = str(content or "")
    if not text:
        return None
    if not any(word in text for word in ("首选", "优先推荐", "推荐", "建议")):
        return None
    match = SKU_RE.search(text)
    if not match:
        return None
    return match.group(0).upper()


